(window.MUSEUM_MATCH_T = window.MUSEUM_MATCH_T || {})["ar"] = {"ui":{"lead":"مباريات عظيمة، نقلةً بعد نقلة. تابع على الرقعة مباريات مشهورة بينما يشرح Musowl كل نقلة.","all":"الكل","k_chess":"الشطرنج","k_shogi":"الشوغي","k_go":"الغو","k_xiangqi":"شيانغتشي","side_r":"الأحمر","res_r":"فوز الأحمر","back":"العودة إلى المباريات العظيمة","start":"البداية","prev":"نقلة إلى الوراء","next":"نقلة إلى الأمام","end":"النهاية","play":"تشغيل تلقائي","pause":"إيقاف","moves":"النقلات","move":"النقلة {n}","startpos":"وضع البداية","nextnote":"الشرح التالي (النقلة {n})","quiet":"لا يوجد شرح لهذه النقلة.","guide":"Musowl","keys":"← → للتنقل نقلةً نقلة","result":"النتيجة","r_event":"المباراة","r_date":"السنة","r_place":"المكان","side_w":"الأبيض","side_b":"الأسود","side_s":"سينتي","side_g":"غوتي","side_B":"الأسود","side_W":"الأبيض","res_w":"فوز الأبيض","res_b":"فوز الأسود","res_d":"تعادل","res_s":"فوز سينتي","res_g":"فوز غوتي","credit":"النقلات هي السجل المعروف لكل مباراة. الشروح من كتابة Musowl في المتحف."},"opera":{"t":"مباراة الأوبرا","w":"بول مورفي","b":"دوق برونزفيك كارل الثاني والكونت إيزوار","ev":"لُعبت في مقصورة بدار أوبرا باريس (الحليفان يتشاوران معًا)","d":"1858","pl":"فرنسا (باريس)","lead":"البطل الأمريكي الشاب في مواجهة نبيلَين، أثناء عرض في الأوبرا: سبع عشرة نقلة. أخرِج القطع بسرعة، وضحِّ بها دون تردد، وأنهِ المباراة بقطع قليلة جدًا. لا توجد مباراة تظهر في كتب الشطرنج أكثر منها.","c":{"0":"باريس، 1858. كان الأمريكي بول مورفي، ابن الحادية والعشرين، يهزم أقوى لاعبي أوروبا واحدًا تلو الآخر. في تلك الليلة، في مقصورة بدار الأوبرا، أخذ دوق برونزويك والكونت إيزوار القطع السوداء معًا وتحدّياه، يتشاوران في كل نقلة. ويُقال إن مورفي أراد أن ينهي المباراة بسرعة ليشاهد العرض. هذه النقلات السبع عشرة مليئة بالأساسيات: أخرِج القطع بسرعة وضع الملك في أمان.","1":"يتقدّم الأبيض ببيدق الملك مربعين. ينظر إلى d5 وe5 في الوسط ويفتح الطريق للفيل والوزير.","2":"يلعب الأسود e5 أيضًا. يتواجه البيدقان في الوسط، ولا يستطيع البيدق الأبيض التقدّم أكثر.","3":"يخرج الحصان إلى f3 ويهاجم بيدق e5. نقلة جيدة: تطوّر قطعة وتجعل الخصم يفكّر في الدفاع.","4":"يحمي الأسود e5 بـ d6. يُسمّى هذا دفاع فيليدور. إنه متين، لكنه يضيّق قليلًا طريق فيل f8.","5":"يلعب الأبيض d4: بيدق آخر إلى الوسط في مواجهة e5. على الأسود أن يختار بين الأخذ والحماية.","6":"الفيل الأسود إلى g4. يضغط على حصان f3 الواقع على خط واحد مع الوزير الأبيض في d1. إذا تحرّك الحصان ضاع الوزير، فلا يستطيع الحصان الذهاب إلى e5.","7":"يأخذ الأبيض في e5 بالبيدق. لو استردّ الأسود فورًا ببيدق d6 لبادل الأبيض الوزيرين ثم أخذ الحصان بيدق e5. لذلك يريد الأسود أولًا التخلّص من حصان f3.","8":"يأخذ الأسود الحصان بالفيل. صار بإمكانه الآن استرداد e5 بأمان. لكن مبادلة الفيل الذي خرج للتو بالحصان تجعل الأسود متأخرًا في التطوير.","9":"يستردّ الأبيض بالوزير الذي يعمل بالفعل قرب الوسط، بينما لم يُخرج الأسود تقريبًا أي قطعة.","10":"يستردّ الأسود ببيدق والعتاد متعادل. لكن الأبيض متقدّم في عدد القطع المطوَّرة.","11":"الفيل إلى c4. مع وزير f3 يصوّب نحو f7. لا يحمي f7 إلا الملك، فهو مربع ضعيف: أخذه يعني كش مات.","12":"يضع الأسود الحصان في f6 ويسدّ العمود f. لولا ذلك لأخذ الوزير f7 بكش مات. الدفاع مع التطوير هو الردّ الصحيح.","13":"ينعطف الوزير إلى b3 ويهاجم f7 وb7 معًا. النقلة ذات التهديدين قوية لأن الخصم لا يستطيع صدّهما معًا.","14":"يضع الأسود الوزير في e7 ليحمي f7 ويترك b7. لكن الوزير الآن يسدّ طريق فيل f8.","15":"لا يأخذ مورفي بيدق b7، بل يُخرج حصانًا. لو أخذه لابتعد الوزير كثيرًا. تفضيل التطوير السريع على بيدق هو أسلوب مورفي تمامًا.","16":"يلعب الأسود c6: يسيطر على d5 وb5 ويفتح طريقًا للوزير نحو b6.","17":"الفيل إلى g5 يثبّت حصان f6. إذا تحرّك الحصان يمكن أخذ الوزير في e7 خلفه. صار تحريك قطع الأسود أصعب فأصعب.","18":"يلعب الأسود b5 ليطرد فيل c4. يكسب مساحة في جناح الوزير، لكنه يفتح ثغرة لدخول قطع الأبيض.","19":"يُضحّى بالحصان ليأخذ في b5! بدل سحب الفيل، يواصل مورفي الهجوم. والملك الأسود ما زال في الوسط، وهذا خطير جدًا على الأسود.","20":"يأخذ الأسود الحصان ويتقدّم بحصان. لكن ملكه ما زال في e8، وقطع الأبيض تواصل التجمّع.","21":"الفيل إلى b5، كش! الملك الأسود ما زال عالقًا في الوسط. للأبيض بيدقان مقابل الحصان، ويتّجه مباشرة نحو الملك.","22":"يسدّ الأسود بالحصان في d7. لكن هذا الحصان مثبّت: إذا تحرّك صار الملك الأسود في كش. الآن سيصوّب الأبيض نحو d7.","23":"يبيّت الأبيض في جهة الوزير. صار الملك آمنًا، وفي الوقت نفسه وصل الرخ إلى d1 ليصوّب نحو d7. نقلة واحدة تدافع وتهاجم: رائعة.","24":"يضع الأسود الرخ في d8 ليحمي d7. ما زال لا يستطيع التبييت، والرخ في h8 والفيل في f8 لا يفعلان شيئًا.","25":"يُضحّى بالرخ ليأخذ في d7! يعطي الأبيض رخًا ليزيل أحد مدافعي الأسود.","26":"يستردّ الأسود بالرخ. الآن هذا الرخ في d7 مثبّت أيضًا: إذا تحرّك أعطى فيل b5 كشًّا للملك الأسود.","27":"يصل الرخ الآخر إلى d1 ويهاجم d7 من جديد. صار عدد القطع البيضاء المهاجِمة لـ d7 أكثر من القطع السوداء المدافِعة.","28":"الوزير الأسود إلى e6، يعرض مبادلة الوزيرين ليُبعد وزير b3 ويريد مساعدة d7. لكن الأوان قد فات.","29":"يأخذ الفيل في d7 مع كش. يزيل الأبيض مدافعي الأسود واحدًا تلو الآخر.","30":"يستردّ الأسود بالحصان. بعد مغادرة الحصان f6 انفتح القطر من فيل g5 إلى d8. وسيكون لهذا القطر دور في النهاية.","31":"يُضحّى بالوزير في b8 مع كش! إنها أشهر نقلة في المباراة. لا بد أن يأخذ الأسود بالحصان، وعندما يغادر الحصان d7 ينفتح العمود d.","32":"يأخذ الأسود بالحصان. الآن لا توجد قطعة سوداء تحمي d8.","33":"الرخ إلى d8، كش مات! فيل g5 يدعم d8، والملك الأسود محاصر بقطعه نفسها فلا مهرب. أعطى الأبيض الوزير والرخ والفيل وأنهى برخ وفيل فقط. طوِّر بسرعة، أمِّن ملكك، وهاجم ما دام ملك الخصم في الوسط: تجمع هذه المباراة الشهيرة كل هذه الأفكار المهمة."}},"reti1910":{"t":"كش مات ريتي","w":"ريتشارد ريتي","b":"سافيلي تارتاكوفر","ev":"مباراة ودية (ليست في بطولة)","d":"1910","pl":"النمسا (فيينا)","lead":"لاعبان سيصبحان من كبار الأساتذة، في مباراة ودية في فيينا، إحدى عشرة نقلة. يضحّي الأبيض بالوزير وينهي المباراة بكش مزدوج: قطعتان تكشّان في الوقت نفسه. ويُسمّى هذا الشكل من الكش مات باسم الأبيض: كش مات ريتي.","c":{"0":"فيينا، 1910. الأبيض ريتشارد ريتي ابن العشرين، والأسود سافيلي تارتاكوفر. أصبح كلاهما من أفضل لاعبي العالم، ويُعرفان بإدخال أفكار جديدة إلى الشطرنج. لم تكن مباراة في بطولة، بل مباراة ودية على رهان صغير. إنها قصيرة، لكنها تُظهر بوضوح لماذا يجب تأمين الملك مبكرًا.","1":"يتقدّم الأبيض ببيدق الملك مربعين. السيطرة على الوسط تسهّل خروج القطع الخلفية. وانفتح الطريق للفيل والوزير.","2":"يلعب الأسود c6. بدل الذهاب إلى الوسط فورًا، يستعد لـ d5 لمهاجمة بيدق e4. يُسمّى هذا الافتتاح المتين دفاع كارو-كان.","3":"يضع الأبيض البيدق الآخر في d4 أيضًا. بيدقان متجاوران في الوسط: للأبيض مساحة كبيرة. سيحاول الأسود تفكيكهما.","4":"كما خُطّط، d5. البيدق يتحدّى e4: \"أستطيع أخذك\". على الأبيض أن يقرّر: الحماية أو التقدّم أو المبادلة.","5":"يُخرج الأبيض حصانًا ليحمي e4. يطوّر قطعة ويدافع في الوقت نفسه دون إضاعة وقت.","6":"يأخذ الأسود بيدق e4. بمبادلة بيادق الوسط يصغر وسط الأبيض.","7":"يستردّ الأبيض بالحصان، فيقف في وسط الرقعة. الحصان في الوسط يصل إلى مربعات كثيرة وهو قوي جدًا.","8":"يُخرج الأسود حصانًا في مواجهة حصان e4. يُلعب هنا غالبًا الفيل إلى f5، لكن الأسود يدعو إلى مبادلة الحصانين.","9":"يخرج الوزير مبكرًا إلى d3 ليحمي حصان e4. عادةً لا يُخرَج الوزير بهذه السرعة، لكن للأبيض خطة. تذكّر أن هذا الوزير يقف على العمود d أمام الملك الأسود.","10":"يلعب الأسود e5 ويعرض بيدقًا ليفتح الطريق للفيل والوزير. نقلة نشطة تُشعل القتال في الوسط.","11":"يأخذ الأبيض بيدق e5. قبل الهدية، لكن الوزير الأسود صار أكثر حرية.","12":"كش! الوزير الأسود في a5 يصوّب قطريًا نحو الملك في e1. وفي الوقت نفسه يريد استرداد بيدق e5: مهمتان في نقلة واحدة. على الأبيض أن يسدّ.","13":"يسدّ الأبيض الكش بالفيل في d2. يمكن للوزير أخذ الفيل، لكن الوزير الأبيض يحميه جيدًا.","14":"استردّ الأسود البيدق وعاد التعادل في العتاد. وهذا الوزير ينظر على العمود e إلى حصان e4 والملك خلفه. إذا تحرّك الحصان صار الملك في كش، فالحصان مقيّد. يبدو أن الأسود سيربحه قريبًا.","15":"يبيّت الأبيض في جهة الوزير. يغادر الملك العمود e فيتحرّر الحصان. وفي الوقت نفسه يصل رخ إلى d1: الرخ في d1 والوزير في d3 والمربع d8 بجانب الملك الأسود صارت على خط واحد. هذا هو فخّ الأبيض.","16":"يأخذ الأسود حصان e4 ويبدو أنه ربح قطعة. لكن الملك الأسود ما زال في e8 ولم يبيّت. قطع الأبيض مصطفّة على العمود d، والملك الأسود بلا حماية. هذه النقلة الخاسرة هي نقطة التحوّل.","17":"الوزير إلى d8، كش! يقدّم الأبيض أقوى قطعه مجانًا. القطعة السوداء الوحيدة التي تستطيع أخذه هي الملك. بتركه يُؤخذ، يجرّ الأبيض الملك إلى المربع الخطِر d8.","18":"لا بد أن يأخذ الأسود بالملك؛ لا طريقة أخرى لصدّ الكش. صار الملك في d8، ورخ d1 ينتظر خلفه.","19":"يتحرّك الفيل من d2 إلى g5 بكش، وفي الوقت نفسه يفتح الطريق لرخ d1 الذي يكشّ أيضًا على العمود d. قطعتان تكشّان معًا: كش مزدوج. لا يمكن صدّه بأخذ قطعة ولا بالسدّ، فعلى الملك أن يهرب.","20":"يهرب الملك إلى c7. لو ذهب إلى e8 لجاء الرخ إلى d8 وأعطى كش مات. أينما ذهب الملك، فالضربة الأخيرة جاهزة لدى الأبيض.","21":"الفيل إلى d8: كش مات على القطر للملك في c7! الفيل يحميه رخ d1، فلا يستطيع الملك أخذه. مربعات مثل b8 وc8 وb7 وc6 مشغولة بقطع الأسود نفسه، والرخ يراقب d6 وd7. في إحدى عشرة نقلة فقط ضحّى الأبيض بالوزير وفاز بقطعتين صغيرتين. تعلّمنا هذه المباراة مدى خطورة السعي وراء العتاد قبل التبييت. وتقول بعض السجلات إن الأسود استسلم قبل ذلك بنقلة."}},"immortal":{"t":"المباراة الخالدة","w":"أدولف أندرسن","b":"ليونيل كيزيريتسكي","ev":"مباراة غير رسمية في استراحة بطولة لندن 1851","d":"1851","pl":"المملكة المتحدة (لندن)","lead":"لندن، أثناء أول بطولة شطرنج دولية: مباراة لُعبت في استراحة. يضحّي الأبيض بفيل ورخّين ثم بالوزير، ويعطي كش مات بالقطع الصغيرة الثلاث الباقية. ويُقال إن الأسود استسلم قبل النهاية، وإن النقلات الأخيرة هي الختام الذي عرضه الأبيض.","c":{"0":"لندن، 1851. في استراحة البطولة، لعب الألماني أندرسن (الأبيض) وكيزيريتسكي نجم باريس (الأسود) مباراة ودية.","1":"يتقدّم الأبيض ببيدق الملك مربعين.","2":"يفعل الأسود الشيء نفسه.","3":"f4! يعرض الأبيض بيدقًا: إنه غامبيت الملك. الفكرة إبعاد بيدق الأسود في e5 عن الوسط.","4":"يأخذ الأسود البيدق.","5":"يخرج الفيل ويصوّب نحو f7 بجانب الملك الأسود.","6":"كش! بعد غياب بيدق f الأبيض صار القطر من h4 إلى e1 مفتوحًا.","7":"يتنحّى الملك جانبًا. لن يستطيع الأبيض التبييت بعد الآن.","8":"يعرض الأسود بيدقًا أيضًا ليجذب الفيل إلى b5.","9":"يأخذه الأبيض.","10":"يخرج حصان ويهاجم بيدق e4.","11":"يُخرج الأبيض حصانًا ويطرد الوزير من h4.","12":"يتراجع الوزير إلى h6.","13":"d3 يحمي e4 ويفتح الطريق لفيل c1.","14":"الحصان إلى h5. الخطة القفز إلى g3 بكش ومهاجمة رخ h1.","15":"الحصان الأبيض إلى h4، مستعدًا للقفز إلى f5 وإزعاج الوزير الأسود.","16":"الوزير الأسود إلى g5 ويهاجم حصان h4.","17":"الحصان إلى f5، مربع جيد يحميه بيدق e4. ويصوّب أيضًا نحو بيدق g7.","18":"c6 يحاول طرد فيل b5.","19":"لا ينقذ الأبيض الفيل: g4 يطارد حصان h5.","20":"يعود الحصان إلى f6.","21":"الرخ إلى g1 يحمي بيدق g4. ويترك الأبيض فيل b5 يذهب. يا لها من جرأة!","22":"يأخذ الأسود الفيل ويتقدّم بقطعة كاملة.","23":"يبدأ بيدق h بمطاردة الوزير الأسود.","24":"الوزير إلى g6.","25":"h5 يطارد الوزير مجددًا.","26":"لا يستطيع الوزير إلا العودة إلى g5. مربعاته تقلّ شيئًا فشيئًا.","27":"الوزير الأبيض إلى f3. إذا أخذ الفيل بعد ذلك في f4 فقد يُحاصَر الوزير الأسود.","28":"يُعيد الأسود الحصان إلى g8 كي يهرب الوزير إلى f6.","29":"يأخذ الفيل بيدق f4 ويهاجم الوزير.","30":"يهرب الوزير إلى f6.","31":"يخرج حصان، ينوي القفز إلى d5 لمهاجمة الوزير.","32":"يخرج الفيل ويصوّب نحو رخ g1.","33":"الحصان إلى d5 يهاجم الوزير في f6 والمربع c7. لا يبالي الأبيض بخسارة رخ g1.","34":"يأخذ الوزير بيدق b2 ويهاجم رخ a1.","35":"الفيل إلى d6! يترك الأبيض الرخّين معًا. وفي المقابل تنسج قطعه شبكة حول الملك الأسود.","36":"يأخذ الأسود رخ g1.","37":"e5! يسدّ هذا البيدق قطر الوزير من b2 إلى g7. لم يعد الوزير الأسود قادرًا على مساعدة ملكه.","38":"يأخذ الأسود الرخ الآخر أيضًا مع كش.","39":"الملك إلى e2. لم يبقَ للأبيض إلا الوزير وحصانان وفيل.","40":"الحصان إلى a6 ليحمي c7. يُقال إن الأسود استسلم هنا تقريبًا، وإن ما يلي هو الختام الذي عرضه الأبيض.","41":"يأخذ الحصان في g7 مع كش.","42":"يهرب الملك إلى d8.","43":"يُضحّى بالوزير في f6 مع كش! تذهب آخر قطعة كبيرة أيضًا.","44":"لا بد أن يأخذ الأسود بالحصان.","45":"الفيل إلى e7، كش مات! حصان d5 يسيطر على e7 وc7، وحصان g7 يسيطر على e8. يفوز الأبيض بفيل واحد وحصانين فقط."}},"mimiaka":{"t":"مباراة الأذنين المحمرّتين","w":"هونينبو شوساكو","b":"إينوي غينان إنسيكي","ev":"مباراة في أوساكا (على ثلاثة أيام)","d":"1846","pl":"اليابان (أوساكا)","lead":"واجه شوساكو، وهو في السابعة عشرة (4 دان)، غينان (8 دان)، أحد أقوى لاعبي عصره. يُروى أن أذني غينان احمرّتا عند النقلة 127، ومن هنا جاء الاسم. لم يكن هناك كومي آنذاك: فاز الأسود بنقطتين.","c":{"0":"أوساكا، 1846. الأسود: شوساكو، 17 عامًا، 4 دان. الأبيض: إينوي غينان إنسيكي، 8 دان، نحو 48 عامًا، من أقوى لاعبي عصره، وقد نافس هونينبو جووا على منصب ميجين غودوكورو. في اليوم السابق بدأ شوساكو بحجرين مسبقين كما يقتضي فارق الدرجة، لكن غينان أدرك قوته سريعًا فأوقف تلك المباراة، ولعب شوساكو هذه بالأسود مباشرة. لم يكن هناك كومي، فلا يُحسب إلا ما على اللوحة من أرض. لنتابع هذه المباراة ذات الأيام الثلاثة نقلةً نقلة.","1":"الأسود 1 على نقطة 3-4 في الأعلى يمينًا (R16). توازن بين أرض الزاوية وإمكان الامتداد على الجانبين. كان شوساكو يحب نقاط 3-4 حين يلعب بالأسود.","2":"الأبيض 2 على نقطة 3-4 في الأعلى يسارًا (D17). في الافتتاح تأتي الزوايا أولًا لأن الأرض تُصنع فيها بأسهل طريقة. يتقاسم الطرفان الزوايا الفارغة.","3":"الأسود 3 على نقطة 3-4 في الأسفل يمينًا (Q3). يتناسق مع R16 بحيث يصبح الجانب الأيمن بين الزاويتين لاحقًا منطقة سوداء كبيرة.","4":"الأبيض 4 (P17) يقترب من زاوية الأسود العليا اليمنى. لو لعب الأسود هناك مرة أخرى لصارت الزاوية متينة جدًا، لذا يتحرك الأبيض أولًا. يستطيع الأسود أن يرد أو أن يأخذ نقطة كبيرة أخرى.","5":"الأسود 5 لا يرد بل يأخذ نقطة 3-4 في الأسفل يسارًا (C4). ثلاث نقاط 3-4 في النقلات 1 و3 و5 نمط يتكرر كثيرًا في مباريات شوساكو بالأسود. التعامل مع P17 يمكن أن ينتظر.","6":"الأبيض 6 (C14) على الجانب الأيسر. المعتاد الاقتراب من الزاوية السفلى اليسرى، لكن غينان يبني على الجانب مع D17. نقلة غير مألوفة قليلًا تمنع مسبقًا C4 من التمدد صعودًا.","7":"الأسود 7 (E4) يغلق الزاوية السفلى اليسرى بحجر ثانٍ، فتصبح شبه مضمونة للأسود. وبالدفاع قبل اقتراب الأبيض يحدّ أيضًا من فعالية الأبيض 6 على اليسار.","8":"الأبيض 8 (R5) يقترب من Q3. مع نقطتي 3-4 سوداوين في طرفي الجانب الأيمن، يحتاج الأبيض موطئ قدم هناك. تبدأ معركة طويلة في الأسفل يمينًا.","9":"الأسود 9 (Q15) يدافع في الأعلى يمينًا. وُضع تحت P17 فيقوّي الزاوية ويدفع P17 نحو الحافة العليا الضيقة. يريد الأسود أن يبقى الجانب الأيمن من نصيبه.","10":"الأبيض 10 (O4) هو «التايشا»: يغطي أحجار الأسود قطريًا من مسافة قصيرة. تفرعاته كثيرة حتى إن مثلًا قديمًا يتحدث عن «وجوه التايشا المئة»، وكان اختصاص غينان. كيف سيواجه شوساكو ابن السابعة عشرة سلاح خصمه المفضل؟","11":"بالنقلة 11 (Q5) يلتصق الأسود بـR5 ويقبل القتال. كان الدفاع الهادئ ممكنًا، لكن شوساكو يختار المسار الكثير التفرعات. تبدأ مبارزة في الحساب.","12":"الأبيض 12 (Q4) يقتحم بين أحجار الأسود ليفصل Q3 عن Q5 ويُضعف أحدهما.","15":"بالنقلتين 13 (P4) و15 (P3) يصل الأسود أحجاره السفلية بإحكام. دخل الأبيض 14 (R4) الزاوية فصارت متنازعًا عليها. يفضّل الأسود البقاء متصلًا وقويًا ولو تنازل عن شيء من الزاوية.","17":"مع الأبيض 16 (P5) والأسود 17 (Q6) تنمو الأحجار صعودًا. يُطل الأسود برأسه نحو الجانب الأيمن، ويضغط الأبيض من الأعلى ليحبسه.","19":"الأبيض 18 (R3) يضيف حجرًا في الزاوية ليعيش، والأسود 19 (O3) يكبح الأبيض في الجانب السفلي. خطة الأسود: ترك الزاوية مقابل القوة في الخارج أسفلًا ويمينًا.","20":"الأبيض 20 (P6) يغطي Q6 من الأعلى محاولًا حبس الأسود منخفضًا على اليمين. إن لم يخرج الأسود صعودًا فستعيش أحجاره اليمنى بالكاد دون مكسب يُذكر.","21":"بالنقلتين 21 (Q7) و23 (Q8) يزحف الأسود صعودًا على الجانب الأيمن بحثًا عن مخرج، بينما يضغط الأبيض 22 (P7) بجانبه. السلسلة السوداء الطويلة على الخط الثالث منخفضة وأرضها قليلة، لكنها حية بوضوح.","24":"الأبيض 24 (N4) يغلق من الخارج حجري الأسود O3–P3 في الأسفل. صارت أحجار الأسود تتجه اتجاهين، يمينًا وأسفل، وحماية الاثنين معًا تزداد صعوبة.","25":"الأسود 25 (N3) يمتد خطوة في الأسفل. تقول الدراسات اللاحقة إن نقلة أخرى تعتمد على «السلّم» كانت أفضل، لذا تُعدّ هذه هفوة الأسود الصغيرة في المباراة. تبقى أحجار الأسود السفلية منخفضة وسهلة التطويق، فتمنح الأبيض فرصة للهجوم المضاد. حتى شوساكو قد يضلّ داخل الشكل المفضل لخصمه.","26":"الأبيض 26 (P8) يغطي أحجار الأسود اليمنى من الأعلى. لا يستطيع الأسود الخروج صعودًا، وهو مهدد بالحبس في الأسفل أيضًا.","28":"الأبيض 28 (M3) يلتصق مباشرة بـN3: نقلة قاسية. توقف تمدد الأسود في الأسفل وتسلبه مساحة الحياة، وتجبره على إضافة أحجار. عاقب غينان هفوة النقلة 25 فورًا.","30":"بعد الأسود 29 (M2) يلتف الأبيض 30 (L2) من الأسفل أيضًا. لا تستطيع أحجار الأسود السفلية الخروج لا نحو الخارج ولا جانبًا. لتعيش عليها الاتصال بالزاوية السفلى اليمنى، فيبدأ سباق أسر حول الزاوية.","31":"الأسود 31 (M4) نقلة مهمة. بدل الاندفاع إلى معركة الزاوية يصنع أولًا نقطة يجب على الأبيض الرد عليها. إنها تحضير للكو الآتي حتمًا.","33":"بالنقلة 33 (R2) يبدأ سباق الأسر في الزاوية السفلى اليمنى. أمّن الأبيض 32 (L3) أحجاره السفلية، فلا بد للأسود من مهاجمة أحجار الأبيض في الزاوية. إن أسرها عاشت أحجاره السفلية، وإلا فهي في خطر.","35":"الأبيض 34 (S2) والأسود 35 (S1): نقلات دقيقة على الخطين الأول والثاني في الزاوية. يقلّص كل طرف حريات الآخر (النقاط الفارغة حول المجموعة) ليأسر أولًا.","36":"الأبيض 36 (N2). قبل بدء الكو يلعب الأبيض أولًا قرب أحجار الأسود السفلية. حتى لو ربح الأسود الكو سيكسب أقل قليلًا: توقيت جيد.","40":"الأبيض 40 (R1) يأسر حجرًا فيتكوّن الكو أخيرًا. في الكو لا يجوز لمن أُسر حجره للتو أن يستردّه فورًا. على الأسود أولًا أن يلعب تهديدًا في مكان آخر يجب على الأبيض الرد عليه، ثم يستردّ. يفوز من يملك تهديدات أكثر.","41":"الأسود 41 (O5) أول تهديد كو. تجاهله يضع أحجار الأبيض في الأسفل يمينًا في ورطة، فيرد الأبيض بـ42 (N5)، ويستردّ الأسود بـ43 (R2). يكلّف قليلًا لكنه ضروري.","44":"الأبيض 44 (S7) تهديد الكو الأبيض. لُعب بجوار أحجار الأسود اليمنى فأجبر الأسود على الرد بـ45 (S8)، ثم استرد الأبيض بـ46 (R1). كل تهديد يحسم جزءًا آخر من اللوحة.","47":"الأسود 47 (M5)، الأبيض 48 (N6)، الأسود 49 (R2): تهديد آخر واسترداد آخر. حول أحجار الأبيض السفلية يضيف الأسود أحجارًا في الخارج شيئًا فشيئًا.","50":"الأبيض 50 (R7) يقطع أحجار الأسود اليمنى: تهديد كبير. عادة كان الأسود سيرد، لكنه يقدّم الكو. تحدث مقايضة كبيرة: يكسب الأبيض على الجانب الأيمن، ويأخذ الأسود الزاوية السفلى اليمنى.","51":"الأسود 51 (P2) يأسر حجرًا ويربح الكو. تصبح الزاوية السفلى اليمنى أرضًا حية للأسود، وتنجو أحجاره السفلية. في المقابل يتابع الأبيض بـ52 (R8) ليشطر أحجار الأسود اليمنى نصفين.","53":"الأسود 53 (R10) فكرة بارعة قلّما يجدها أحد. يأتي لنجدة الجزء العلوي من أحجار الأسود اليمنى المنقسمة من الجهة الأخرى لأحجار الأبيض. لو رد الأسود ردًا بسيطًا لأخذ الأبيض جزءًا كبيرًا من الجانب الأيمن.","56":"الأبيض 54 (S10) والأسود 55 (S11) والأبيض 56 (S9): يعيش الأبيض على الحافة اليمنى، ويكبحه الأسود من الأعلى محتفظًا بالنصف العلوي من الجانب.","59":"بعد الأسود 57 (M6) والأبيض 58 (N7) يصل الأسود 59 (R11) أحجاره اليمنى بإحكام. صار جانب الأسود الأيمن آمنًا من أعلاه إلى أسفله. تبدو المقايضة الكبيرة متكافئة تقريبًا.","60":"الأبيض 60 (S3) نقلة كبيرة. تقلّص أرض الأسود في الزاوية وتقوّي أحجار الأبيض، وتتيح لاحقًا لعب 62 (M1) كنقلة يجب على الأسود الرد عليها.","63":"الأبيض 62 (M1) يأسر حجرًا والأسود 63 (O1) يصل: انتهت المعركة الطويلة في الأسفل يمينًا مؤقتًا. للأبيض أرض في الأسفل، وللأسود جدار سميك على اليمين. وبسبب النقلة 25 جزئيًا يُعتقد أن الأبيض لعب أفضل حتى الآن. لكن جدار شوساكو سيعمل كثيرًا لاحقًا في الوسط.","65":"الأبيض 64 (G3) يمتد نحو يسار الجانب السفلي ليكبّر منطقته أكثر. والأسود 65 (G5) يغطيه من الأعلى كي لا تكبر صعودًا. يتضح النمط: الأبيض يأخذ الأرض، والأسود القوة الخارجية.","66":"الأبيض 66 (C9) على الجانب الأيسر. مع الأبيض 6 (C14) يبني هناك أيضًا إطارًا أبيض. يجمع الأبيض الأرض في الأسفل واليسار.","67":"الأسود 67 (L17) على الجانب العلوي. مستندًا إلى جداره السميك يسعى إلى إطار كبير — منطقة واسعة قد تصير أرضًا — من الأعلى نحو الوسط. وفي الوقت نفسه يضع P17 في كماشة.","69":"الأبيض 68 (J17) يدخل يسار L17 ليشطر إطار الأسود العلوي. والأسود 69 (Q17) يلتصق بـP17 فيهاجمه ويقوّي الزاوية.","70":"الأبيض 70 (O10) يتوسط جدار الأسود الأيمن وإطاره العلوي. يمنع الإطار من الالتحام عبر الوسط ويحاول الاتصال بأحجار الأبيض اليمنى.","72":"الأبيض 72 (P13) نقلة رائعة. وُضع فوق جدار الأسود مباشرة فأنشأ مأوى أبيض في قلب إطار الأسود. حتى لو طارده الأسود يستطيع الأبيض الإفلات بخفة. تقلصت آمال الأسود في الأعلى بهذه النقلة.","73":"الأسود 73 (P12) يسدّ أسفل P13 كي لا يتصل بأحجار الأبيض اليمنى. ثم يدخل الأبيض 74 (Q18) الزاوية العليا اليمنى ليقتطع من أرضها أيضًا.","77":"بعد الأسود 75 (R18) الذي يحمي الزاوية، يأتي الأبيض 76 (O13) والأسود 77 (N11). يغطي الأسود أحجار الأبيض في الوسط ليكسب الأرض بالهجوم. من هنا حتى النقلة 100 تقريبًا لا يتهاون غينان أبدًا ويتفادى كل الهجمات.","79":"الأبيض 78 (N10) يصل أحجاره في الوسط، والأسود 79 (O16) يقوّي الأعلى. لم يكسب الأسود كثيرًا من الهجوم، لكنه يحتفظ بأرض الأعلى بأمان.","80":"بالنقلتين 80 (Q12) و82 (Q13) يصل الأبيض أحجارًا بجوار جدار الأسود مباشرة. ومع شكل متين داخل إطار الأسود ستكون أرض الأسود في الأعلى يمينًا أصغر من المأمول.","83":"الأسود 83 (H3) يدخل أرض الأبيض السفلية التي كبرت كثيرًا. ثم الأبيض 84 (H2) والأسود 85 (J2): معركة دقيقة حول ما إذا كان الأسود سيعيش في الداخل أو يهرب إلى الخارج.","87":"الأبيض 86 (J3) والأسود 87 (H4) والأبيض 88 (K2): يصل الأسود أحجاره المتسللة بـG5 ويُخرجها. تتقلص أرض الأبيض السفلية ويزيد الأسود سُمكه في الوسط.","89":"الأسود 89 (F17) يقترب من D17 ويضع حجرًا أسود يسار الجانب العلوي، فيكبح تمدد الأبيض. ويحاول الأبيض 90 (M17) و92 (N17) إحياء أحجاره بين أحجار الأسود في الأعلى.","93":"بالنقلتين 93 (M18) و95 (N16) يضغط الأسود أحجار الأبيض العليا من فوق ومن تحت. لا يستطيع الأبيض أن يعيش إلا منخفضًا على الخطين الأول والثاني، وبأرض قليلة جدًا.","96":"منذ الأبيض 96 (R14) تبدأ معركة دقيقة بجوار زاوية الأسود العليا اليمنى. يفصل الأبيض جدار الأسود عن الزاوية ليُضعف أحجاره. يرد الأسود بـ97 (Q14)، ويتقدم الأبيض على الحافة اليمنى بـ98 (R12) و100 (S12).","101":"بالنقلتين 101 (T12) و103 (T13) ينزل الأسود إلى الخط الأول على الحافة اليمنى فيضيّق مساحة حياة الأبيض. تبدو نقلات الحافة صغيرة، لكنها هنا تحسم الحياة والموت.","104":"الأبيض 104 (Q10) يضرب نقطة ضعف في جدار الأسود الأيمن. بعد الأسود 105 (Q11) والأبيض 106 (P11) يذهب الأسود للأسر بالنقلة 107.","107":"الأسود 107 (P10) يأسر حجرًا أبيض. صار جدار الأسود الأيمن متصلًا بإحكام وآمنًا. ويخرج الأبيض 108 (O11) و110 (P9) نحو الوسط لحماية أحجاره القريبة من الجدار.","112":"منذ الأبيض 112 (L18) تسارع أحجار الأبيض العليا إلى الحياة. ويطوّقها الأسود بـ113 (K18) و115 (K17) و117 (K19) كي لا تخرج.","118":"الأبيض 118 (M19) يأسر حجرًا فتعيش مجموعته العليا. العيش داخل إطار الأسود يقلّص أرضه كثيرًا. لعب غينان حتى الآن ممتاز.","120":"الأسود 119 (D18) يجسّ زاوية الأبيض العليا اليسرى، ويرد الأبيض بـ120 (C17). لا يريد الأسود الزاوية، بل تقوية يسار الجانب العلوي لكسب أرض.","122":"الأسود 121 (F15) يرتّب شكله من الأعلى نحو الوسط. والأبيض 122 (C6) يلعب بجوار زاوية الأسود السفلى اليسرى ليقتطع من أرضها شيئًا فشيئًا.","124":"الأسود 123 (G2) والأبيض 124 (J1) والأسود 125 (F3): تُحسم الحدود يسار الأسفل. يأسر الأبيض هناك حجرًا ويحافظ على أرضه.","126":"الأبيض 126 (J5). الأبيض سميك في الأسفل ومستعد للتقدم نحو الوسط. بأرضه في الأسفل واليسار ومجموعته الحية في الأعلى يمينًا يتقدم الأبيض. يُقال إن معظم المحترفين الحاضرين رأوا الأبيض متقدمًا. لن يلحق الأسود بنقلات عادية.","127":"هذه هي نقلة «الأذنين المحمرّتين» الشهيرة، الأسود 127 (K11). يُقال إن هذا الحجر في وسط اللوحة يعمل في أربعة اتجاهات معًا: صعودًا يوسّع إطار الأسود، ونزولًا يوقف سُمك الأبيض، ويمينًا يسند جدار الأسود، ويسارًا يصد تمدد الأبيض. نقلة واحدة بأربع مهام. ومن هنا تبدأ المباراة، التي بدت في صالح الأبيض، بالميل تدريجيًا نحو الأسود.","128":"عندما لُعبت النقلة 127 لاحظ طبيب يراقب قريبًا أن أذني غينان احمرّتا. لم يكن يعرف الكثير عن الغو، لكنه يُروى أنه رأى في ذلك علامة اضطراب وتوقّع فوز الأسود. وبينما ظن المحترفون أن الأبيض أفضل، التقطت عين الطبيب وحدها نقطة التحول. الأبيض 128 (E18) يدافع عن الزاوية العليا اليسرى.","131":"بعد أن يقوّي الأسود يسار الأعلى بـ129 (F18)، يدخل الأسود 131 (D10) إطار الأبيض على الجانب الأيسر. ولأن الحجر 127 يسند الوسط يستطيع الأسود الاقتحام بأمان.","136":"بالنقلتين 133 (E10) و135 (D12) تتسلل أحجار الأسود اليسرى بين أحجار الأبيض وتتخذ شكلًا. ويأتي الأبيض 136 (J10) إلى الوسط ليُضعف أثر الحجر 127، فلا يمكنه ترك الوسط للأسود.","140":"الأسود 137 (H7) يغطي أحجار الأبيض السفلية، ويحاول الأبيض 138 (G10) و140 (F8) وصل أحجاره يسار الوسط. في الوسط تتشابك الأحجار ولكلا الطرفين نقاط ضعف.","143":"الأبيض 142 (E2) يتسلل إلى زاوية الأسود السفلى اليسرى. ويصل الأسود 143 (D7) و145 (D6) أحجاره وعينه على أحجار الأبيض اليسرى وعلى المتسلل في الزاوية معًا.","147":"الأسود 147 (K10) يمتد مباشرة إلى الأسفل من الحجر 127 فيشطر أحجار الأبيض في الوسط يمينًا ويسارًا. هنا يبدأ الحجر 127 في إظهار قوته الحقيقية.","150":"الأبيض 148 (K9) والأسود 149 (L9) والأبيض 150 (J11): يحاول الأبيض وصل أحجار الوسط، ويقطعها الأسود عن الأسفل. ويحط الأبيض 150 بجوار الحجر 127 مباشرة ليدخل وسط الأسود أيضًا.","155":"من الأسود 151 (J9) إلى الأسود 155 (K12) يضغط الأسود أحجار الأبيض في الوسط من الجهتين. الأسود 155 يتصل فوق الحجر 127 فيوحّد وسط الأسود مع الأعلى. المبادرة في الوسط للأسود.","160":"بعد الأبيض 156 (C5) والأسود 157 (D5) يلعب الأبيض 158 (J12) و160 (H8). يحمي أحجاره في الوسط ويستهدف ضعفًا لدى الأسود في الأسفل يسارًا. ما زالت المباراة متقاربة ولا يمكن لأحد التهاون.","162":"الأسود 161 (B8) يدخل تحت أحجار الأبيض اليسرى. والأبيض 162 (D13) يغطي أحجار الأسود اليسرى من الأعلى ليضيّق عليها.","167":"بعد تقوية الوسط بـ163 (G12) و165 (J13) يأتي الأسود 167 (C2) نقلة دقيقة تحمي الزاوية السفلى اليسرى. لو أُهملت لاستطاع حجر الأبيض 142 (E2) تهديد الزاوية. يزيل الأسود الخطر أولًا ويبني موقفًا يصعب خسارته.","169":"الأبيض 166 (E17) و168 (F16) يحاولان قطع أحجار الأسود في الأعلى يسارًا. يرد الأسود بـ169 (G16) و171 (G17) واصلًا أحجاره العليا بإحكام.","175":"الأسود 175 (G4) يأسر حجرًا أبيض. تنجو أحجار سوداء داخل منطقة الأبيض السفلية، فأرضها أصغر مما بدت. يضيق الفارق تدريجيًا.","180":"الأبيض 176 (M11) والأسود 177 (L13) والأبيض 178 (J6) والأسود 179 (M10) والأبيض 180 (M13): يمين الوسط أيضًا يضع الأبيض أحجارًا في إطار الأسود ليقلّصه. يرد الأسود محوّلًا الوسط كله إلى أرضه.","187":"من الأسود 183 (K13) إلى 187 (M14) يضغط الأسود من الأعلى على أحجار الأبيض في الوسط ويبعدها عن الأعلى. يكافح الأبيض ليعيش، لكن جدار الأسود سميك والمعركة شاقة عليه.","195":"من الأبيض 190 (G14) إلى 194 (M9) يوسّع الأبيض منافذ أحجاره في الوسط. ويقتحم الأسود 195 (L10) بينها ليكسر شكلها.","199":"مع الأسود 199 (K7) تهدأ معركة الوسط. تنجو أحجار الأبيض في الوسط بالكاد، لكن الأسود كسب أرضًا في الطريق وصارت المباراة تميل إليه. تأتي الآن النهاية: تثبيت الحدود، حيث تحسم نقطة أو نقطتان كل شيء.","208":"الأسود 203 (E19) و205 (F2) والأبيض 208 (R19): تُلعب نقلات النهاية على الحواف من الأكبر إلى الأصغر. في النهاية من المهم لعب النقلات التي يجب على الخصم الرد عليها أولًا.","212":"بالنقلتين 212 (D19) و216 (F19) يأسر الأبيض أحجارًا سوداء على الحافة العليا، ويعوّض الأسود في مكان آخر بـ213 (G11) و217 (G19). لا يتراجع أحد.","225":"الأسود 225 (L6) يأسر حجرًا أبيض ويواصل اقتطاع أرض الأبيض في منتصف الأسفل. تقترب المعركة الكبيرة الأخيرة: كو في الوسط.","228":"الأبيض 228 (N12) يأسر حجرًا فيصنع كو في الوسط. لأكثر من 80 نقلة سيتبادل الطرفان الأسر في M13 وN13. كل تهديد يُحدث مقايضة صغيرة في مكان ما. يبدأ الكو الطويل جدًا الذي سيحسم المباراة.","236":"الأبيض 236 (T8) يأسر حجرًا في منتصف الكو. يرى بعض المحللين أن إغلاق الكو هنا كان سيقلص الفارق. في الكو الطويل تحدد المقايضات المختارة النقطة أو النقطتين الأخيرتين.","262":"بالنقلتين 262 (T1) و266 (S4) يأسر الأبيض أحجارًا سوداء في الزاوية السفلى اليمنى. في الأثناء استرد الأسود في مكان آخر، ويستمر الكو مع مكاسب وخسائر لدى الطرفين.","275":"الأسود 275 (T14) يأسر حجرين أبيضين، وهذه المقايضة على الحافة العليا اليمنى لصالحه. وبجمع مقايضات الكو يحافظ الأسود على تقدمه الطفيف.","299":"الأسود 299 (J16) يأسر أربعة أحجار بيضاء دفعة واحدة. زال تهديد الأبيض في الأعلى وصار أعلى الأسود آمنًا. تجاوز الأسود آخر أزمة كبيرة في الكو.","311":"الأسود 311 (M13) يغلق الكو أخيرًا. انتهى كو الوسط الذي دام أكثر من 80 نقلة. وعبر كل المقايضات حافظ الأسود على تقدمه. لم تبق إلا نقلات نهاية صغيرة.","321":"من الأسود 317 (N1) إلى 321 (M2) تُثبَّت آخر الحدود في الأسفل. يواصل الطرفان اللعب بدقة حتى النهاية لكسب ولو نقطة واحدة.","325":"تنتهي المباراة بعد 325 نقلة، ويُظهر العدّ تقدّم الأسود بنقطتين. تعثّر الأسود قليلًا في التايشا المفضّلة لدى غينان في البداية، وكان الأبيض يُعدّ أفضل حتى منتصف اللعب. قلب شوساكو المجرى بحجر النقلة 127، وصمد في الكو الطويل، وحافظ على تقدم ضئيل. يُروى أن غينان قال لاحقًا إن قوة شوساكو لم تكن دون مستوى 7 دان. صنعت هذه المباراة اسم شوساكو، وصار لاحقًا وريث بيت هونينبو. التايشا في الافتتاح، ونقلة الأذنين المحمرّتين 127، والكو الطويل في النهاية: هذه أبرز محطات هذه المباراة العظيمة."}},"evergreen":{"t":"المباراة دائمة الخضرة","w":"أدولف أندرسن","b":"جان دوفرين","ev":"مباراة ودية (ليست في بطولة)","d":"1852","pl":"ألمانيا (على الأرجح برلين)","lead":"أندرسن، صاحب المباراة الخالدة، لعب هذه التحفة الأخرى بعد عام. في اللحظة التي يهدّد فيها الأسود بالكش مات، يحرّك الأبيض رخًا بهدوء، ثم يضحّي بالوزير وينهي بكش مزدوج. تُسمّى \"دائمة الخضرة\" لأنها لا تذبل أبدًا.","c":{"0":"مباراة نُشرت في مجلة عام 1852. الأبيض أندرسن، والأسود صديقه دوفرين. يُعتقد أنها لُعبت في برلين، لكن لا يوجد سجل يؤكد ذلك.","1":"يتقدّم الأبيض ببيدق الملك مربعين.","2":"يفعل الأسود الشيء نفسه.","3":"الحصان يهاجم بيدق e5.","4":"يحمي الأسود e5 بحصان.","5":"يخرج الفيل ويصوّب نحو f7.","6":"يُخرج الأسود فيلًا أيضًا.","7":"b4! عرض بيدق يُسمّى غامبيت إيفانز. بينما يأخذه الأسود، يقوّي الأبيض الوسط.","8":"يأخذ الأسود البيدق.","9":"c3 يطارد الفيل ويستعد لـ d4.","10":"يتراجع الفيل إلى a5.","11":"d4 يحتل الوسط.","12":"يأخذ الأسود البيدق.","13":"لا يستردّ الأبيض، بل يبيّت. سلامة الملك ونشاط القطع قبل البيادق.","14":"يتقدّم البيدق الأسود حتى d3، في عمق معسكر الأبيض.","15":"الوزير إلى b3. مع فيل c4 يصوّب نحو f7.","16":"يحمي الأسود f7 بالوزير.","17":"e5 يطارد الوزير.","18":"الوزير إلى g6.","19":"الرخ إلى e1، على العمود e ليدعم بيدق e5.","20":"يُخرج الأسود حصانًا استعدادًا للتبييت.","21":"الفيل إلى a3 يصوّب قطريًا نحو حصان e7. إذا تحرّك هذا الحصان وصل الفيل إلى f8، فصار التبييت القصير صعبًا على الأسود.","22":"يعرض الأسود بيدقًا ليُبعد قطع الأبيض.","23":"يأخذه الوزير.","24":"الرخ إلى b8 يطارد الوزير على العمود b.","25":"الوزير إلى a4.","26":"يتراجع الفيل إلى b6.","27":"يخرج حصان. صارت كل قطع الأبيض تقريبًا في اللعب.","28":"يُخرج الأسود الفيل الآخر.","29":"الحصان إلى e4، وعينه على f6.","30":"الوزير الأسود إلى f5 ويهاجم حصان e4.","31":"يأخذ الفيل بيدق d3 ويحمي حصان e4.","32":"الوزير إلى h5 يصوّب نحو حصان f3.","33":"يُضحّى بالحصان في f6 مع كش!","34":"يأخذ الأسود ببيدق.","35":"يستردّ الأبيض ببيدق ويهاجم حصان e7. وعلى العمود e يراقب رخ e1 المربع e7 أيضًا.","36":"الرخ إلى g8 يصوّب نحو g2. إذا أخذ وزير h5 في f3 صار الكش مات قريبًا.","37":"نقلة رخ هادئة إلى d1! ملك الأبيض في خطر، لكن بدل الدفاع يصوّب الأبيض نحو d7. هذه النقلة هي ما جعل المباراة \"دائمة الخضرة\".","38":"يأخذ الأسود حصان f3. الأخذ في g2 بعدها سيكون كش مات.","39":"لكن الدور للأبيض أولًا. يأخذ الرخ حصان e7 مع كش!","40":"يستردّ الأسود بالحصان من c6. صار القطر من a4 إلى d7 مفتوحًا.","41":"يُضحّى بالوزير في d7 مع كش!","42":"لا بد أن يأخذ الأسود بالملك.","43":"يتحرّك الفيل إلى f5 بكش ويفتح العمود d لرخ d1: كش مزدوج.","44":"الملك إلى e8. لو ذهب إلى c6 لأعطى الفيل كش مات في d7.","45":"الفيل إلى d7، كش.","46":"الملك إلى f8.","47":"فيل a3 يأخذ حصان e7: كش مات! فيل d7 يسيطر على e8، وبيدق f6 يسيطر على e7 وg7."}},"lasker1912":{"t":"صيد الملك","w":"إدوارد لاسكر","b":"جورج آلان توماس","ev":"مباراة سريعة ودية في نادي مدينة لندن للشطرنج","d":"1912","pl":"المملكة المتحدة (لندن)","lead":"مباراة سريعة وودية في نادٍ بلندن. يضحّي الأبيض بالوزير ويطارد الملك الأسود عبر الرقعة كلها، من g8 إلى g1. تختلف ترتيبات نقلات الافتتاح قليلًا بين السجلات، لكن الوضع بعد النقلة العاشرة هو نفسه.","c":{"0":"أكتوبر 1912، نادي مدينة لندن للشطرنج. الأبيض إدوارد لاسكر، مهندس شاب وصل لتوّه من ألمانيا، والأسود جورج آلان توماس الذي صار لاحقًا بطل بريطانيا. كانت مباراة سريعة وودية. وهي مشهورة باسم \"صيد الملك\": يُطارَد الملك الأسود من g8 حتى g1 في الطرف الآخر من الرقعة. انتقل لاسكر لاحقًا إلى أمريكا واشتهر بكتبه في الشطرنج.","1":"يبدأ الأبيض بـ d4، بيدق الوزير. يسيطر على e5 وc5 ويفتح الطريق لفيل c1.","2":"يلعب الأسود e6: وضع متين أولًا، مع التحضير لـ f5 أو d5.","3":"الحصان إلى f3. يسيطر على e5 ويساعد في حماية جناح الملك: أكثر المربعات طبيعية.","4":"يلعب الأسود f5 ويسيطر على e4، كما في الدفاع الهولندي. لكن تحريك بيدق أمام الملك يُضعفه قليلًا.","5":"الحصان الآخر إلى c3، استعدادًا لـ e4 لضرب بيدق f5.","6":"يُخرج الأسود حصانًا إلى f6: يزيد سيطرته على e4 ويستعد للتبييت.","7":"الفيل إلى g5 يصوّب نحو حصان f6. هذا الحصان مدافع مهم عن الملك الأسود، لذا يريد الأبيض إزالته مبكرًا.","8":"يضع الأسود الفيل في e7 ليحمي الحصان ويقترب من التبييت.","9":"يبادل الأبيض الفيل بالحصان. اختفى الحصان الذي كان يحمي الملك الأسود.","10":"يستردّ الأسود بالفيل. الآن يتولّى فيل f6 حماية جناح الملك.","11":"e4! يضرب الأبيض بيدق f5 ويكسب مساحة في الوسط. تنفتح الخطوط وتتحرّك قطع الأبيض بحرية أكبر.","12":"يأخذ الأسود بيدق e4. وإلا لعب الأبيض e5 ودفع قطع الأسود إلى الخلف.","13":"يستردّ الحصان ويستقر في الوسط، ينظر إلى فيل f6 والمربعين g5 وd6.","14":"يلعب الأسود b6 ليضع الفيل في b7 ويصوّب على القطر الطويل نحو حصان e4.","15":"الحصان إلى e5، مربع قوي في الوسط يرى أيضًا g4 وf7. صار الحصانان الأبيضان قريبين من جناح ملك الأسود.","16":"يبيّت الأسود. الملك في g8. لكن بغياب بيدق f توجد ثغرات كثيرة حول الملك.","17":"الفيل إلى d3. حصانه في e4 يعترضه الآن، لكن خلفه بيدق h7. ما إن يتحرّك حصان e4 حتى يصوّب هذا الفيل مباشرة نحو h7.","18":"الفيل الأسود إلى b7 يصوّب على القطر الطويل نحو حصان e4 ويقيّد قطع الأبيض.","19":"الوزير إلى h5 يصوّب نحو بيدق h7 الذي لا يحميه إلا الملك الأسود. وزير الأبيض وفيله وحصاناه كلها موجّهة نحو الملك الأسود.","20":"يضع الأسود الوزير في e7. يحمي فيل f6 ويستعد للذهاب إلى c5، لكنه لا يرى فكرة الأبيض. كان لا بد من h6 أو أخذ حصان e5. هذه نقطة التحوّل.","21":"يُضحّى بالوزير في h7 مع كش! يقدّم الأبيض أقوى قطعه مجانًا. كان لاسكر يرى الطريق كله لمطاردة الملك حتى الكش مات.","22":"لا بد أن يأخذ الأسود بالملك، فيصير الملك في h7.","23":"يأخذ الحصان فيل f6 مع كش. وفي الوقت نفسه يخلو e4، فيكشّ فيل d3 أيضًا الملك في h7: كش مزدوج. لا يمكن سدّه، فعلى الملك أن يهرب.","24":"الملك إلى h6. لو ذهب إلى h8 لقفز الحصان الآخر إلى g6 بكش مات. يُدفع الملك إلى الأمام أكثر فأكثر.","25":"يقفز الحصان الآخر من e5 إلى g4 بكش، يهاجم الملك في h6 ويدفعه أبعد.","26":"الملك إلى g5: يترك معسكره ويمشي نحو جهة الأبيض.","27":"كش ببيدق h! حتى البيادق تشارك في الصيد. على الملك أن يواصل التقدّم.","28":"الملك إلى f4. عبر منتصف الرقعة ويدخل معسكر الأبيض.","29":"كش مرة أخرى ببيدق g. بيدقان يسدّان طريق العودة على الملك.","30":"الملك إلى f3، في وسط قطع الأبيض تمامًا.","31":"يتراجع الفيل من d3 إلى e2 بكش. يُدفع الملك إلى عمق أكبر.","32":"الملك إلى g2. لم يعد الملك الأبيض في e1 بعيدًا.","33":"الرخ إلى h2، كش. أخيرًا يدخل الرخ اللعب.","34":"يصل الملك أخيرًا إلى g1. انطلق من g8 وبلغ الصف الأول في الطرف الآخر من الرقعة.","35":"يتحرّك الملك الأبيض من e1 إلى d2. ينفتح بذلك طريق رخ a1 الذي يكشّ الملك في g1 على الصف الأول: كش مات! كان التبييت الطويل سيعطي كش مات أيضًا، لكن لاسكر حرّك الملك. في مباراة سريعة، وبعد التضحية بالوزير، طارد الأبيض الملك أربع عشرة نقلة حتى أعمق زاوية في معسكره. مباراة نادرة جدًا."}},"toketsu":{"t":"مباراة الدم","w":"أكابوشي إنتيتسو","b":"هونينبو جووا","ev":"لُعبت في دار السيد ماتسودايرا حاكم سوو (على أربعة أيام)","d":"1835","pl":"اليابان (إيدو)","lead":"مباراة وُلدت من الصراع على منصب «ميجين غودوكورو»، أعلى منصب في الغو الياباني. أرسل إينوي غينان إنسيكي تلميذه أكابوشي إنتيتسو لمواجهة الميجين جووا. بعد أربعة أيام من القتال خسر إنتيتسو، ويُروى أنه سعل دمًا أمام اللوحة.","c":{"0":"1835. الأسود: أكابوشي إنتيتسو (7 دان)، والأبيض: الميجين هونينبو جووا. أرسل غينان أفضل تلاميذه ليقول إن ميجين يخسر أمام لاعب 7 دان لا يستحق اللقب.","1":"الأسود 1 على نقطة 3-4 في الأسفل يسارًا (C4). يبدأ إنتيتسو بهدوء.","4":"بعد أربع نقلات في كل زاوية حجر: الأبيض في الأسفل يمينًا والأعلى يسارًا، والأسود في الأسفل يسارًا والأعلى يمينًا.","6":"الأبيض 6 (E3) يقترب مبكرًا من زاوية الأسود السفلى اليسرى. جووا نشِط منذ البداية.","10":"الأبيض 10 (P4) يغلق الزاوية السفلى اليمنى بحجر ثانٍ.","12":"الأبيض 12 (D6) يضغط من الأعلى على زاوية الأسود السفلى اليسرى. هنا تبدأ أكبر معارك المباراة.","13":"الأسود 13 (E4) يلتصق مباشرة بحجر أبيض. يقبل الأسود القتال.","20":"الأبيض 20 (C3) يتسلل تحت زاوية الأسود: يقتطع من أرض الزاوية ويحاول في الوقت نفسه إحياء أحجاره.","28":"الأبيض 28 (C9) يمتد بعيدًا على الجانب الأيسر. كثيرًا ما يُعدّ تمددًا مبالغًا فيه، نقلة عنيفة على طريقة جووا.","33":"الأسود 33 (C2). يُروى أنها تفرّعة جديدة درستها مدرسة إينوي سرًّا. تهاجم أحجار الأبيض العائمة في الوسط وتبتلع في الوقت نفسه أحجاره على الجانب الأيسر.","36":"الأبيض 36 (F3). يحاول الأبيض حصر الأسود من الخارج في الأسفل يسارًا مع وصل أحجاره.","43":"الأسود 43 (E9). أحجار الأبيض على اليسار في ورطة. حتى الآن لعب إنتيتسو جيدًا ويُعتقد أنه تقدّم.","45":"الأسود 45 (D11) يمتد صعودًا على الجانب الأيسر، فيُبقي أحجار الأبيض منفصلة ويقوّي أحجاره.","50":"الأبيض 50 (C16). يترك الأبيض الأسفل يسارًا مؤقتًا ويتجه إلى الزاوية العليا اليسرى.","53":"الأسود 53 (G17). يدخل الأسود الجانب العلوي كي لا يوسّع الأبيض الزاوية العليا اليسرى.","58":"الأبيض 58 (C14) يمتد من الزاوية العليا اليسرى على طول الجانب ويقترب من أحجار الأسود على اليسار.","60":"الأبيض 60 (G4) يأسر حجرين أسودين. تتنفس مجموعة الأبيض في الأسفل يسارًا قليلًا أخيرًا.","62":"الأبيض 62 (J17). يتواجه الطرفان في الأعلى أيضًا. هناك أحجار ضعيفة في كل مكان: موقف صعب.","66":"الأبيض 66 (B14). حول الزاوية العليا اليسرى يعمل الأبيض على تثبيت أحجاره.","68":"الأبيض 68 (B11). اشتهرت نقلات الأبيض التالية، مع النقلة 80، بأنها نقلات جووا العبقرية. كانت مدهشة لدرجة أن الناس قالوا إن الأشباح هي التي أرتها له.","70":"الأبيض 70 (E12). بدل الرد على الأسود مباشرة في اليسار، يلعب الأبيض أولًا نقطة مفتاحية أخرى. الإمكانيات الخفية المتبقية تسمح بذلك.","72":"الأبيض 72 (R13). يتجه الأبيض إلى الجانب الأيمن كي لا تكبر منطقة الأسود في الأعلى يمينًا.","76":"الأبيض 76 (O14). يربط الأبيض الجانب الأيمن بالوسط ويستعد لتقسيم أحجار الأسود.","80":"الأبيض 80 (Q10) يصنع «مثلثًا فارغًا»، وهو شكل يُعدّ سيئًا عادة. لكن هذه النقلة صارت قاعدة لشطر الأسود نصفين ومهاجمته. وهي المثال الكلاسيكي على نقلة قبيحة المظهر لكنها ممتازة.","83":"الأسود 83 (R3) يدخل زاوية الأبيض السفلى اليمنى، فتندلع هناك معركة شرسة من الأسر وإعادة الأسر.","91":"الأسود 91 (Q4) يأسر حجرًا أبيض. الزاوية السفلى اليمنى مهمة جدًا للأسود.","98":"الأبيض 98 (M4). يطوّق الأبيض أحجار الأسود في الأسفل ولا يدعها تعيش بسهولة.","106":"الأبيض 106 (S5) يأسر حجرًا أسود. يحتفظ الأبيض بالزاوية السفلى اليمنى، وعلى أحجار الأسود الهرب إلى الخارج.","113":"الأسود 113 (K6). تبحث أحجار الأسود في الأسفل عن الحياة بالخروج نحو الوسط.","120":"الأبيض 120 (N9) يسدّ طريق أحجار الأسود الهاربة. في الوسط صار السؤال: أيّ الأحجار تضعف أولًا؟","128":"الأبيض 128 (L11) يضغط أحجار الأسود في الوسط من الأعلى أيضًا. لا يستطيع الأسود الاطمئنان بعد.","138":"الأبيض 138 (K8) يأسر حجرًا فيبدأ كو في الوسط. لنحو 30 نقلة يتناوب الطرفان الأسر في K8 وL8.","152":"الأبيض 152 (E11) تهديد كو. أثناء الكو يجد الأبيض في كل مكان نقلات يجب على الأسود الرد عليها.","170":"الأبيض 170 (P15). هدأ كو الوسط، فيتجه الأبيض إلى الأعلى يمينًا مستهدفًا مجموعة سوداء كبيرة لم تعش تمامًا بعد.","178":"الأبيض 178 (J14) يقفز إلى وسط المنطقة العليا ليفصل أحجار الأسود يمينًا ويسارًا. الهجوم الفاصل الذي حُضّر منذ النقلة 80 يبدأ الآن بجدية.","193":"الأسود 193 (J11) يأسر حجرًا أبيض. يقاتل الأسود بشدة ليتصل ويعيش.","201":"الأسود 201 (R14) يأسر حجرًا فيبدأ كو جديد على الجانب الأيمن، بأسرٍ متبادل في R14 وR15.","206":"الأبيض 206 (M13). حتى أثناء الكو يشدّ الأبيض الخناق تدريجيًا على أحجار الأسود في الوسط.","222":"الأبيض 222 (L14) يأسر حجرًا. تبقى أحجار الأسود في الأعلى منقسمة، وإنقاذ القسمين معًا يزداد صعوبة.","230":"الأبيض 230 (C13) يضرب نقطة ضعف الأسود على الجانب الأيسر أيضًا. أحجار الأبيض صارت متصلة بقوة في أنحاء اللوحة.","237":"بالنقلتين 237 (F12) و239 (E13) يستردّ الأسود أحجارًا في الأعلى يسارًا. ومع ذلك لا يتقلص الفارق الكلي.","246":"بعد الأبيض 246 (L8) استسلم إنتيتسو. يُروى أنه سعل دمًا على اللوحة أثناء جمع الأحجار. ربما كان مريضًا منذ مدة، وتوفي بعد ذلك بقليل. وتُعدّ هذه المباراة أعظم انتصار في حياة جووا."}},"deepblue1997":{"t":"انتصار ديب بلو","w":"ديب بلو (حاسوب IBM)","b":"غاري كاسباروف","ev":"المباراة السادسة من مواجهة الثأر مع ديب بلو من IBM (لقاء من ست مباريات)","d":"1997","pl":"الولايات المتحدة (نيويورك)","lead":"بطل العالم كاسباروف في مواجهة ديب بلو، حاسوب شطرنج صنعته IBM، في لقاء من ست مباريات. كانت النتيجة متعادلة بعد خمس مباريات، وانتهت الأخيرة في 19 نقلة فقط. كانت أول مرة يهزم فيها حاسوب بطل العالم في لقاء كامل من عدة مباريات.","c":{"0":"نيويورك، 11 مايو 1997. فاز كاسباروف بلقائهما في العام السابق. هذه المرة النتيجة 2½–2½ بعد خمس مباريات. ديب بلو بالأبيض.","1":"يتقدّم الأبيض ببيدق الملك مربعين.","2":"يلعب كاسباروف c6: دفاع كارو-كان.","3":"يضع الأبيض البيدق الآخر في الوسط.","4":"يلعب الأسود d5 ضد e4.","5":"الحصان يحمي e4.","6":"يأخذ الأسود بيدق e4.","7":"يستردّ الحصان.","8":"يضع الأسود حصانًا في d7 ليُخرج الحصان الآخر إلى f6 بعد ذلك.","9":"يقفز الحصان إلى g5: خطة حادّة تصوّب نحو f7 وe6.","10":"يُخرج الأسود الحصان إلى f6.","11":"الفيل إلى d3 ينظر إلى جناح ملك الأسود.","12":"يقوّي الأسود الدفاع بـ e6.","13":"يخرج الحصان الآخر إلى f3.","14":"يلعب الأسود h6 لطرد حصان g5. لكن في هذا الوضع كانت التضحية بالحصان للأبيض معروفة من قبل. ويُقال إنه كان اختيارًا غريبًا من كاسباروف.","15":"يُضحّى بالحصان في e6! يُقال إن ديب بلو لعب هذه النقلة من نقلات الافتتاح المخزّنة لديه مسبقًا.","16":"لا يأخذ الأسود فورًا، بل يضع الوزير في e7. على العمود e يصوّب نحو حصان e6 والملك الأبيض خلفه.","17":"يبيّت الأبيض ويضع ملكه في أمان.","18":"يأخذ الأسود الحصان ويتقدّم في العتاد.","19":"الفيل إلى g6، كش. بغياب بيدق f7 يصل القطر إلى الملك.","20":"الملك إلى d8. لم يعد الأسود قادرًا على التبييت، وبقي الملك قرب الوسط.","21":"يخرج الفيل الآخر ويصوّب نحو المربعات حول الملك الأسود.","22":"يلعب الأسود b5 ليفسح مكانًا في جناح الوزير للملك والفيل.","23":"a4 يضرب بيدق b5.","24":"يضع الأسود الفيل في b7.","25":"الرخ إلى e1. على العمود e ينظر إلى بيدق e6، وخلفه إلى الوزير في e7.","26":"الحصان الأسود إلى d5 ويهاجم فيل f4.","27":"يتراجع الفيل إلى g3.","28":"الملك الأسود إلى c8، أكثر أمانًا قليلًا.","29":"يأخذ الأبيض بيدق b5.","30":"يستردّ الأسود.","31":"الوزير إلى d3 ينظر إلى بيدق b5 والمربع f5.","32":"يحمي الأسود b5 بالفيل.","33":"الفيل إلى f5! يمكن أخذه مجانًا.","34":"يأخذ الأسود ببيدق. لكن بذلك يختفي بيدق العمود e.","35":"يأخذ الرخ الوزير في e7. أعطى الأبيض حصانًا وفيلًا ورخًا، لكنه كسب الوزير.","36":"يستردّ الأسود الرخ بالفيل.","37":"c4! يضرب البيدق b5 وd5 معًا، ويبدأ دفاع الأسود بالانهيار. استسلم كاسباروف هنا، ربما لأنه رأى ملكه مكشوفًا أكثر من أن يوقف الهجوم. لقد فاز حاسوب بلقاء ضد بطل العالم."}},"seigen1933":{"t":"مباراة 3-3 ونقطة النجم والتنغن","w":"غو سيغن","b":"هونينبو شوساي","ev":"مباراة تذكارية مع الميجين (أكثر من ثلاثة أشهر)","d":"1933–1934","pl":"اليابان (طوكيو)","lead":"لعب غو سيغن، وهو في التاسعة عشرة (5 دان)، ضد الميجين هونينبو شوساي. بالأسود افتتح على نقطة 3-3، ثم على نقطة نجم، ثم في المركز تمامًا (تنغن)، محطّمًا أعراف زمانه ومُدهشًا عالم الغو. مع توقفات كثيرة استمرت المباراة أكثر من ثلاثة أشهر، وفاز الأبيض بنقطتين.","c":{"0":"1933. في ذلك العام كان غو سيغن وصديقه كيتاني مينورو ينشران أسلوب افتتاح جديدًا يُسمّى «شين فوسيكي». أراد الجميع أن يروا كيف سيستعمله أمام الميجين.","1":"الأسود 1 على نقطة 3-3 في الأعلى يمينًا (R17). يضمن الزاوية بنقلة واحدة، لكن تأثيره نحو الخارج ضعيف، ولم يكن أحد آنذاك يراه نقلة افتتاح.","3":"الأسود 3 على نقطة النجم في الأسفل يسارًا (D4). على عكس 3-3، يهتم بالتوسع نحو الخارج.","5":"الأسود 5 يذهب إلى مركز اللوحة تمامًا: التنغن (K10). لا زاوية ولا جانب، بل الوسط. أمام الميجين عرض غو سيغن أفكاره الجديدة صراحة.","6":"3-3 والنجم والتنغن: لكل حجر أسود دور مختلف: أرض الزاوية، والامتداد نحو الخارج، وقوة الوسط. بالنقلة 6 (Q16) يلعب الأبيض بجوار حجر 3-3 الأسود مباشرة.","9":"الأسود 9 (P18). يستقر الأسود في الزاوية العليا اليمنى بشكل مضغوط وآمن، أسلوب يقدّم الأرض أولًا كما يليق بنقطة 3-3.","11":"الأسود 11 (K4) في منتصف الجانب السفلي تحت التنغن مباشرة. بالتعاون معه يطمح الأسود إلى منطقة كبيرة في الأسفل.","12":"الأبيض 12 (M3) يدخل فورًا الجانب السفلي كي لا يبني الأسود إطارًا كبيرًا. يحافظ الميجين على هدوئه ويفكك خطط الأسود واحدة تلو الأخرى.","13":"الأسود 13 (D10)، هذه المرة في منتصف الجانب الأيسر. أحجار الأسود عالية وتشكّل معًا إطارًا واسعًا.","14":"الأبيض 14 (E16) يغلق الزاوية العليا اليسرى بحجر ثانٍ. لا يرتبك الميجين أمام الأسلوب الجديد ويؤمّن الزاوية بهدوء.","21":"الأسود 21 (G10) يربط التنغن بحجر الجانب الأيسر، فينتشر نفوذ الأسود في الوسط.","28":"الأبيض 28 (D3) يتسلل تحت حجر النجم الأسود في الأسفل يسارًا ويأخذ الزاوية. يتنازل الأسود عنها مقابل قوة في الخارج.","30":"الأبيض 30 (Q12) يمتد على الجانب الأيمن ويضع غطاءً فوق زاوية 3-3 السوداء، فيُضعف امتدادها.","37":"الأسود 37 (P15) يأسر حجرًا أبيض. في الأعلى يمينًا يتصادم الطرفان في معركة متقاربة.","40":"الأبيض 40 (O10) يخرج من الجانب الأيمن نحو الوسط ويقترب من نفوذ الأسود حول التنغن.","44":"الأبيض 44 (H17) يحتل نقطة على الجانب العلوي ليوقف امتداد الأسود نحو الأعلى.","45":"الأسود 45 (R7) يبدأ العمل على موقع الأبيض في الأسفل يمينًا. تتبعه معركة طويلة من الجانب الأيمن نزولًا إلى تلك الزاوية.","59":"الأسود 59 (R4) يدخل الزاوية السفلى اليمنى أيضًا ويقلّص أرض الأبيض.","70":"الأبيض 70 (N6) يتقدم من الجانب السفلي نحو الوسط ليفصل أحجار الأسود في الأسفل يمينًا عن أحجار الوسط.","79":"الأسود 79 (L9) يقوّي الوسط حول حجر التنغن. حتى الآن تبدو المباراة متوازنة إلى حد كبير.","80":"الأبيض 80 (C6) يصعد من الزاوية السفلى اليسرى على الجانب الأيسر مستهدفًا أحجار الأسود هناك.","98":"الأبيض 98 (A11) يأسر حجرين أسودين. يعيش الأبيض بإتقان على الحافة اليسرى، ويصبح جانب الأسود الأيسر أصغر مما خُطّط له.","101":"الأسود 101 (S14) يعود إلى الأعلى يمينًا ليقلّص موقع الأبيض على الجانب الأيمن.","105":"الأسود 105 (K17) يحتل منتصف الجانب العلوي ويبدأ مهاجمة أحجار الأبيض هناك.","117":"الأسود 117 (F17) يدخل أيضًا محيط زاوية الأبيض العليا اليسرى، فيتحول الجانب العلوي كله إلى ساحة قتال.","124":"الأبيض 124 (K15) يقود أحجاره العليا نحو الوسط ويقطع بين أحجار الأسود في طريقه.","135":"الأسود 135 (E9) يأسر حجرين أبيضين. يستعيد الأسود شيئًا على الجانب الأيسر.","138":"الأبيض 138 (N18) يثبّت أرضًا على الجانب العلوي. على اللوحة كلها الوضع متقارب جدًا.","153":"الأسود 153 (K14). تشكّل أحجار الأسود في الوسط طريقًا سميكًا يصل الأعلى بالأسفل. والسؤال الحاسم: كيف سيخترق الأبيض هذا السُّمك؟","159":"الأسود 159 (F4) يدافع بثبات في الأسفل يسارًا. نقلة الأبيض التالية هي الأشهر في المباراة.","160":"الأبيض 160 (H8) يقفز إلى ثغرة في سُمك الأسود: نقلة حادة بأهداف متعددة، ومنها يبدأ الأبيض اختراق وسط الأسود. انتشرت إشاعة بأن تلميذًا، لا شوساي، هو من وجدها، لكن ذلك لم يثبت قط.","161":"الأسود 161 (J8) يردّ فورًا، لكن للأبيض أكثر من هدف.","162":"الأبيض 162 (K12) ينتقل إلى الجزء العلوي من الوسط ويهدد روابط أحجار الأسود.","172":"الأبيض 172 (F13) يصل أحجار الوسط بالأعلى يسارًا. شيئًا فشيئًا يتوقف سُمك الأسود في الوسط عن التحول إلى أرض.","178":"الأبيض 178 (N9) يدخل منطقة الأسود يمين الوسط أيضًا.","187":"بالنقلتين 187 (M6) و189 (L7) يردّ الأسود بأسر أحجار بيضاء. ومع ذلك كان الأبيض قد سبق إلى النقاط المهمة.","198":"الأبيض 198 (E12) يأسر حجرًا. وتتصل أحجار الأبيض في الأعلى يسارًا أيضًا، فيتقدم الأبيض قليلًا إجمالًا.","203":"الأسود 203 (B3). من هنا تبدأ النهاية: تُثبَّت الحدود على الحواف نقطة نقطة.","224":"الأبيض 224 (T10) يأسر حجرًا. حتى على الحافة اليمنى لا يتنازل الأبيض عن نقطة واحدة.","233":"الأسود 233 (L13) يأسر حجرين أبيضين. يواصل الأسود المطاردة حتى النهاية.","252":"تنتهي المباراة بعد 252 نقلة: فاز الأبيض بنقطتين. بلا كومي كان للأسود أفضلية صغيرة بالبدء أولًا، لكن الميجين ثبت حتى النهاية. ومع ذلك أحدثت افتتاحية غو سيغن (3-3 والنجم والتنغن) ضجة كبيرة وبشّرت بعصر جديد في الافتتاحيات."}},"century1956":{"t":"مباراة القرن","w":"دونالد بيرن","b":"بوبي فيشر","ev":"بطولة كأس روزنوالد الثالثة (بطولة روزنوالد التذكارية)","d":"1956","pl":"الولايات المتحدة (نيويورك)","lead":"بوبي فيشر، ابن الثالثة عشرة، يهزم دونالد بيرن، أحد أقوى أساتذة أمريكا. في النقلة 17 يترك فيشر وزيره يُؤخذ مجانًا، ثم يستعيد القطع واحدة تلو الأخرى، وفي النهاية تطارد قطعه الصغيرة الملك الأبيض. وأصبح فيشر لاحقًا بطلًا للعالم.","c":{"0":"نيويورك، 17 أكتوبر 1956، مباراة في بطولة. يلعب بالأسود فيشر ابن الثالثة عشرة، وبالأبيض بيرن، أحد أفضل اللاعبين الأمريكيين.","1":"يبدأ الأبيض بحصان.","4":"يلعب فيشر g6 ليضع الفيل على القطر الطويل.","8":"يبيّت الأسود: الملك في أمان أولًا.","10":"يلعب الأسود d5. يبدأ الصراع على الوسط.","15":"بـ e4 صار للأبيض بيدقان متجاوران في الوسط.","17":"الرخ إلى d1 يدعم بيدق d4. لم يبيّت الأبيض بعد.","18":"يذهب الحصان إلى b6 ويطارد الوزير في c4.","20":"الفيل إلى g4 يضغط على حصان f3.","21":"الفيل الأبيض إلى g5. ما زال الملك الأبيض في الوسط.","22":"الحصان إلى a4! يقفز إلى مربع يمكن أخذه فيه. الفكرة: إذا ابتعد حصان c3 فقد بيدق e4 حاميه.","23":"لا يأخذ الأبيض الحصان، وينقل الوزير إلى a3.","26":"يأخذ الحصان الأسود بيدق e4. وسط الأبيض ينهار.","27":"يأخذ الفيل الأبيض بيدق e7 ويهاجم في الوقت نفسه الوزير الأسود ورخ f8.","28":"الوزير إلى b6! يترك الأسود رخ f8. يعتمد فيشر على أن الملك الأبيض ما زال في الوسط.","29":"لا يأخذ الأبيض الرخ، بل يُخرج الفيل.","30":"يأخذ الحصان بيدق c3 ويهاجم رخ d1.","31":"الفيل إلى c5 يهاجم الوزير الأسود في b6.","32":"كش من الرخ على العمود e!","33":"الملك إلى f1. الآن لن يستطيع الأبيض التبييت أبدًا.","34":"الفيل إلى e6! أشهر نقلة في المباراة: يترك الأسود وزيره يُؤخذ مجانًا. وفي المقابل لديه خطة لاستعادة القطع واحدة تلو الأخرى.","35":"يأخذ الأبيض الوزير الأسود.","36":"الفيل إلى c4، كش. يبدأ الهجوم المضاد للأسود.","38":"يكشّ الحصان من e2.","40":"حين يعود الملك إلى f1 يتحرّك الحصان فيكشف كشًّا من فيل c4. وفي طريقه يلتقط الحصان بيدق d4.","44":"يعود الحصان إلى c3، كش مكشوف آخر، ويهاجم الآن رخ d1. إعطاء الكش مرة بعد مرة مع جمع القطع يُسمّى \"الطاحونة\".","46":"يستردّ الأسود الفيل. وما زال حصان c3 يهاجم رخ d1.","50":"يأخذ الحصان رخ d1. الآن استعاد الأسود أكثر من الوزير وصار متقدّمًا بوضوح.","52":"يأخذ الرخ بيدق a2 أيضًا.","56":"يبادل الأسود الرخاخ. كلما قلّت القطع كان ذلك أفضل لمن يملك أكثر.","57":"الوزير الأبيض يكشّ.","58":"يسدّ الأسود بالفيل.","64":"b5. يبدأ البيدق الأسود بالتقدّم.","68":"يذهب الملك إلى g7 ويحرّر فيل f8.","70":"الآن تطارد القطع السوداء الملك الأبيض. كش بفيل.","72":"يكشّ الحصان في g3.","74":"كش بالفيل الآخر.","76":"الفيل إلى b3، كش.","78":"يكشّ الحصان في e2.","80":"يكشّ الحصان في c3. يُطارَد الملك هنا وهناك.","82":"الرخ إلى c2: كش مات! الرخ والفيلان والحصان يعملون معًا. أظهر فتى في الثالثة عشرة كيف تلعب قطع كثيرة كفريق واحد."}},"oshiro1849":{"t":"أول مباراة قلعة لشوساكو","w":"هونينبو شوساكو","b":"ياسوي سانتشي التاسع","ev":"مباراة القلعة (المباراة السنوية في قلعة إيدو)","d":"1849","pl":"اليابان (إيدو)","lead":"كانت مباريات القلعة المناسبة السنوية الكبرى التي يلعب فيها لاعبو بيوت الغو الرسمية في قلعة الشوغون. شارك شوساكو، وهو في العشرين، لأول مرة في ذلك العام وفاز بالأسود بفارق 11 نقطة، فبدأ سجلًا مثاليًا من 19 فوزًا في 19 مباراة قلعة.","c":{"0":"1849. في العام السابق اختير شوساكو وريثًا لبيت هونينبو، وها هو يلعب أول مباراة قلعة له. يُقال إن هذه المباريات كانت تُلعب غالبًا مسبقًا في مكان آخر ثم يُعاد رصّها في القلعة فقط.","1":"الأسود 1 على نقطة 3-4 في الأعلى يمينًا (R16). كعادته يبدأ شوساكو بنقطة 3-4 هادئة.","4":"الأبيض 4 (C15) يقترب من حجر الأسود في D17 في الأعلى يسارًا. تبدأ هناك معركة مبكرة.","5":"الأسود 5 (C11) يضغط على الحجر الأبيض المقترب من الأسفل بكماشة، كي لا يستقر الأبيض بسهولة على اليسار.","12":"الأبيض 12 (C17). يأخذ الأبيض الزاوية العليا اليسرى، ويحصل الأسود على أحجار متجهة نحو الخارج: مقايضة عادلة.","13":"الأسود 13 (J17) يستفيد من الأحجار الخارجية ويمتد على الجانب العلوي.","15":"الأسود 15 (C5) يأخذ آخر زاوية فارغة في الأسفل يسارًا. صارت الزوايا الأربع كلها مشغولة.","16":"الأبيض 16 (E4) يقترب فورًا من ذلك الحجر الأسود، فتبدأ معركة في الأسفل يسارًا أيضًا.","19":"الأسود 19 (D2) يؤمّن الزاوية السفلى اليسرى بثبات: اختيار متين على طريقة شوساكو.","23":"الأسود 23 (E5) يخرج بين أحجار الأبيض ويقوّي مجموعته في الأسفل يسارًا.","29":"الأسود 29 (F11) يقوّي أحجاره على اليسار ويتطلع في الوقت نفسه إلى الوسط.","30":"الأبيض 30 (H4) يمتد في الأسفل، يضغط على مجموعة الأسود اليسرى ويبني منطقته.","31":"الأسود 31 (O3) يقترب من زاوية الأبيض السفلى اليمنى.","33":"الأسود 33 (R3) يلتصق بحجر الأبيض في الزاوية. من هنا يبني الأسود في الخارج، بينما يزحف الأبيض على الخط الثالث عند الحافة.","43":"الأسود 43 (Q8). يمتد الآن جدار أسود سميك على الجانب الأيمن. أخذ الأبيض أرض الزاوية والحافة، وكسب الأسود قوة خارجية.","44":"الأبيض 44 (L17) يدخل بين أحجار الأسود على الجانب العلوي كي لا تكبر منطقة الأسود كثيرًا.","50":"الأبيض 50 (R18) يتسلل تحت زاوية الأسود العليا اليمنى مستهدفًا أرض الزاوية.","51":"الأسود 51 (P13). مستندًا إلى الجدار، يرسم الأسود منطقة كبيرة من الجانب الأيمن نحو الوسط.","52":"الأبيض 52 (D10) يقتحم بين أحجار الأسود على الجانب الأيسر، فتتشابك الأحجار هناك.","63":"الأسود 63 (B10) يلعب على الحافة اليسرى كي لا تجد أحجار الأبيض قاعدة هناك.","65":"الأسود 65 (G3) يدخل أيضًا منطقة الأبيض في الأسفل ويقلّص أرضه.","73":"الأسود 73 (K17) يقوّي أحجاره العليا ويضغط على حجر الأبيض من النقلة 44.","76":"الأبيض 76 (P11) يقفز داخل منطقة الأسود على الجانب الأيمن. حياة هذا الحجر أو موته ستغيّر النتيجة كثيرًا.","77":"الأسود 77 (Q11) يرد من جهة جداره ويدفع الأبيض نحو الوسط: دفاع هادئ يهاجم أيضًا، على طريقة شوساكو.","80":"الأبيض 80 (N10) يهرب نحو الوسط محاولًا الإفلات من مطاردة الأسود.","85":"الأسود 85 (N12) يواصل الهجوم مع توسيع أرضه في الأعلى واليمين. الكسب عبر الهجوم: لعب بارع.","91":"الأسود 91 (J7) يلعب فوق أحجار الأبيض السفلية ويغطي منطقة الأبيض من جهة الوسط أيضًا.","100":"الأبيض 100 (S17) يحاول شيئًا في الزاوية العليا اليمنى ليقلّص أرض الأسود.","119":"الأسود 119 (R17) يدافع بثبات عن الزاوية العليا اليمنى ويصدّ محاولة الأبيض.","122":"الأبيض 122 (G6) يلتف حول أحجار الأسود في الأسفل يسارًا من الخارج محاولًا قطعها عن وسط الأسود.","131":"الأسود 131 (M5) يدقّ إسفينًا في منطقة الأبيض وسط الجانب السفلي.","140":"الأبيض 140 (B4) يحاول شيئًا في زاوية الأسود السفلى اليسرى، فتبدأ معركة أسر متقاربة على الحافة اليسرى.","156":"الأبيض 156 (A8) يأسر حجرين أسودين. تهدأ معركة الحافة اليسرى بعد أن أخذ كل طرف قليلًا.","158":"الأبيض 158 (L10). ما زالت للأبيض أحجار في الوسط، ويحاول تقليص أرض الأسود هناك.","162":"الأبيض 162 (O12) يأسر حجرًا أسود. ومع ذلك تبقى منطقة الأسود على اليمين كبيرة.","172":"الأبيض 172 (K18). من هنا تبدأ النهاية، بدءًا بالحدود على الجانب العلوي.","186":"الأبيض 186 (T16) يقتطع من أرض الأسود عند الحافة العليا اليمنى. في النهاية يلعب الطرفان أكبر النقاط أولًا.","205":"الأسود 205 (Q18) يغلق الجزء الأيمن من الجانب العلوي ويثبّت أرضه هناك.","223":"الأسود 223 (P10) يثبّت الحدود بين أرض الأسود على اليمين وأحجار الأبيض التي فرّت إلى الوسط.","233":"الأسود 233 (Q9) يأسر حجرًا أبيض. صارت أرض الأسود على اليمين آمنة تقريبًا بالكامل.","239":"الأسود 239 (A6) يأسر حجرًا فيظهر كو على الحافة اليسرى. يستمر الصراع على كل نقطة حتى النهاية.","260":"الأبيض 260 (T6) يأسر حجرًا ويصنع كو آخر عند الحافة السفلى اليمنى. يستردّ الأسود بالنقلة 263 (T5).","267":"تنتهي المباراة بعد 267 نقلة: فاز الأسود بفارق 11 نقطة. بلا مغامرات: هاجم شوساكو وترك أرضه تنمو بشكل طبيعي، فوز يشبهه تمامًا. وكانت الأولى من 19 انتصارًا متتاليًا في مباريات القلعة."}},"shilin":{"t":"مباراة «شيلين غوانغجي»","w":"الأحمر (لم يُحفظ اسمه)","b":"الأسود (لم يُحفظ اسمه)","ev":"موسوعة الحياة اليومية «شيلين غوانغجي»: «مباراة فاز فيها من أعطى النقلة الأولى، بمدفعين من الجهة نفسها»","d":"القرن الثالث عشر","pl":"الصين (سونغ–يوان)","lead":"هذا السجل مأخوذ من «شيلين غوانغجي»، وهي موسوعة للحياة اليومية جمعها تشن يوانجينغ في أواخر عهد سلالة سونغ وبدايات يوان. ويُقال إنه من أقدم سجلات الشيانغتشي الكاملة الباقية. إنها مباراة نموذجية يترك فيها اللاعب الأقوى النقلة الأولى لخصمه، وفي تسع نقلات فقط يحاصر الحصانُ الأسود العربةَ الحمراء.","c":{"0":"يزيد عمر هذا السجل على 700 عام، وهو من الزمن الواقع بين سلالتي سونغ ويوان. يرد في باب الألعاب من موسوعة «شيلين غوانغجي»، ويُقال إنه من أقدم مباريات الشيانغتشي الكاملة التي بقيت لنا. لم تُحفظ أسماء اللاعبين. يقول العنوان إن اللاعب الأقوى «أعطى النقلة الأولى» للأضعف، فهي درس يبيّن كيف يخسر الأحمر الذي يبدأ. الأحمر في الأسفل ويبدأ اللعب.","1":"ينقل الأحمر المدفع الأيمن إلى العمود الأوسط. هذا هو «المدفع المركزي» الذي يصوّب مباشرة على الجنرال الأسود، وما زال من أقوى الافتتاحيات حتى اليوم. ونرى أنه كان يُلعب قبل 700 عام.","2":"يردّ الأسود بمدفع إلى الوسط أيضًا، فيتواجه المدفعان. عندما يحرّك الطرفان المدفع من الجهة نفسها يُسمّى ذلك «مدفعين في اتجاه واحد». ومعركة المدفع ضد المدفع محبوبة منذ قرون.","3":"يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. هذا الجندي مهدَّد من المدفع الأسود ويحتاج إلى حارس. والحصان يستعد أيضًا للتقدّم.","4":"يفعل الأسود الشيء نفسه ويحمي جنديه الأوسط بحصان. يبني الطرفان أولًا قاعدة متينة.","5":"ينقل الأحمر العربة اليمنى خطوة إلى الجانب نحو عمود مفتوح. العربة أقوى قطعة على الرقعة، لذلك من الجيد تشغيلها مبكرًا.","6":"يُخرج الأسود الحصان الآخر ويترك العربتين في البيت الآن. الخطة هي تقديم القطع أولًا. لكن العربة التي تخرج متأخرة قد يصعب استخدامها في الهجوم لاحقًا.","7":"تعبر العربة الحمراء النهر دفعة واحدة وتدخل معسكر الأسود. تريد تهديد القطع السوداء، لكن بقية القطع الحمراء ما زالت في البيت، فالهجوم متسرّع قليلًا. كان يمكن أيضًا إخراج الحصان أو العربة اليسرى أولًا.","8":"يقدّم الأسود جندي العمود 3 خطوة واحدة. بهذا يفتح طريقًا للحصان ليقفز إلى الأمام لاحقًا. يكاد الأسود يدعو العربة الحمراء إلى القدوم.","9":"تأخذ العربة الحمراء جنديًا وتصوّب الآن على الحصان الأسود خلفه. كسب قطعة وتهديد أخرى يبدو رائعًا. لكن العربة تقدّمت بعيدًا جدًا ولا صديق حولها. والعربة الوحيدة في معسكر العدو يسهل مطاردتها.","10":"يقفز الحصان الأسود إلى الأمام. يهرب من العربة ويقترب من معسكر الأحمر في الوقت نفسه: مهمتان بنقلة واحدة. سيكون هذا الحصان بطل المباراة.","11":"يعيد الأحمر العربة خطوة إلى الوراء ليهاجم الحصان من الجانب. العربة تأخذ من بعيد، فلا يستطيع الحصان أن يرتاح. ومع ذلك لا تساعد هذه النقلة على إخراج قطع حمراء أخرى.","12":"يتقدّم الحصان الأسود أكثر ويعبر النهر إلى معسكر الأحمر. وفي كل مرة يهرب فيها من العربة يقترب أكثر من الجنرال الأحمر.","13":"يقدّم الأحمر جنديًا ليفتح الطريق لحصانه. الفكرة إخراجه ومبادلته بالحصان الأسود. لكن هذا يمنح الأسود وقتًا ليتقدّم أكثر.","14":"يرفع الأسود فيلًا ويهاجم العربة الحمراء. طرد عربة الخصم بقطعة دفاعية أمر فعّال جدًا. على الأحمر أن يحرّك العربة مرة أخرى، ويكسب الأسود نقلة إضافية.","15":"تنزلق العربة الحمراء جانبًا وتأخذ جنديًا آخر. صار الأحمر متقدّمًا بجنديين، لكن هذه هي النقلة الخاسرة. فالعربة الآن بعيدة عن جنرالها ولا تستطيع العودة للدفاع. كان على الأحمر أن يحتاط من الحصان، كأن يعيد العربة إلى البيت.","16":"يتوغّل الحصان الأسود أعمق ويهاجم العربة الحمراء. وهناك المزيد: إذا قفز مرة أخرى فسيكشّ الجنرال الأحمر ويهاجم في الوقت نفسه العربة في زاوية الأحمر. حصان واحد صنع تهديدين معًا.","17":"يطارد الأحمر الحصان بالعربة. لكن لم يعد من الممكن إيقافه. لم يبقَ حول الجنرال الأحمر أحد يساعد.","18":"يقفز الحصان مع كِش! وهو يهاجم أيضًا العربة في زاوية الأحمر، فإذا تنحّى الجنرال ضاعت العربة. تسع نقلات فقط، لكن المباراة تعلّمنا ماذا يحدث لعربة تندفع وحدها، ولماذا يجب أن تقاتل القطع معًا. قبل 700 عام كان اللاعبون يفكّرون في الأشياء نفسها على الرقعة نفسها."}},"qima13":{"t":"التضحية بالحصان في ثلاث عشرة نقلة («جوتشونغمي»)","w":"الأحمر (لم يُحفظ اسمه)","b":"الأسود (لم يُحفظ اسمه)","ev":"«جوتشونغمي»، الجزء الأول، المباراة الأولى","d":"1632 (سنة النشر)","pl":"الصين (مينغ)","lead":"هذه أول مباراة في كتاب «جوتشونغمي» («السرّ في داخل اليوسفية»)، وهو كتاب شيانغتشي نشره تشو جينتشن من عهد سلالة مينغ سنة 1632. يترك الأحمر للأسود أن يأخذ حصانًا مجانًا، ويندفع في الهجوم أثناء ذلك، ويُميت في ثلاث عشرة نقلة. وما زالت محبوبة بعد نحو 400 عام باسم «التضحية بالحصان في ثلاث عشرة نقلة».","c":{"0":"هذه المباراة الأولى في كتاب «جوتشونغمي» الذي طُبع سنة 1632 قرب نهاية سلالة مينغ. ويُعدّ مع «كتيّب زهر البرقوق» اللاحق أحد الكتابين الكلاسيكيين الكبيرين في الشيانغتشي. ليست مباراة حقيقية بل نموذج كُتب لتعليم خطة، لذلك لا توجد أسماء لاعبين. الأحمر في الأسفل ويبدأ، وينتهي كل شيء في ثلاث عشرة نقلة فقط.","1":"ينقل الأحمر المدفع الأيمن إلى الوسط. هذا هو «المدفع المركزي» الذي يحدّق مباشرة في الجنرال الأسود. واشتهر كتاب «جوتشونغمي» بدراسة طرق الهجوم بهذه الافتتاحية.","2":"ينقل الأسود أيضًا المدفع من الجهة نفسها إلى الوسط. هذان «مدفعان في اتجاه واحد» يتصادمان وجهًا لوجه. كل طرف يصوّب على الجندي الأوسط للآخر.","3":"يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. يحمي الجندي الذي يصوّب عليه المدفع الأسود، ويبدأ الحصان العمل.","4":"يحمي الأسود أيضًا الجندي الأوسط بحصان. حتى الآن الشكلان متماثلان.","5":"يقدّم الأحمر العربة اليمنى خطوة واحدة فقط. الآن تستطيع في النقلة التالية أن تجري جانبًا. العربة التي تتحرك جانبيًا هكذا تُسمّى «العربة الأفقية»، وتستطيع الانتقال بسرعة إلى أي جناح.","6":"يحرّك الأسود العربة خطوة إلى الجانب لتتمكن من الصعود مستقيمة. هذه «عربة مستقيمة». العربة الأفقية ضد العربة المستقيمة: طريقتان مختلفتان لاستخدام العربة وجهًا لوجه.","7":"تنتقل العربة الأفقية الحمراء إلى عمود على اليسار. هذا العمود يمرّ بجوار المستشار الأسود مباشرة، حيث الدفاع ضعيف. يستعد الأحمر للاقتحام من هنا.","8":"تعبر العربة المستقيمة السوداء النهر وتتوغّل في معسكر الأحمر. يريد الأسود أن يردّ بهجوم من عنده. لكنها نقلة تستعجل الهجوم قبل الدفاع.","9":"تندفع العربة الحمراء إلى عمق معسكر الأسود. تقف على «عين» الفيل، وهي النقطة التي يجب أن يمرّ بها الفيل، فلا يستطيع الفيل الأسود التحرك. وبجوار المستشار صارت قريبة جدًا من الجنرال.","10":"يُخرج الأسود الحصان الآخر نحو الحافة. ومن أهدافه منع العربة الحمراء من التسلّل من الجانب.","11":"ها هي التضحية بالحصان! يرفع الأحمر العربة الأخرى خطوة واحدة. يترك هذا الحصانَ في الزاوية اليسرى بلا حارس، فيستطيع المدفع الأسود أخذه مجانًا. لكن الأحمر يكسب مقابل حصان واحد الوقتَ لإدخال العربتين في الهجوم بسرعة.","12":"يأخذ المدفع الأسود الحصان الأحمر. يبدو أن الأسود كسب قطعة. لكن هذا المدفع صار بعيدًا عن بيته ولا يستطيع المساعدة في الدفاع. ويُقال إن الأفضل هنا كان رفع مستشار لتقوية الدفاع بدل الأخذ.","13":"يتقدّم المدفع الأحمر. مستخدمًا المدفع الأسود في الوسط «حاجزًا» يقفز فوقه، يصوّب الآن على الحصان الأسود خلفه. المدفع قطعة عجيبة تأخذ بالقفز فوق قطعة واحدة بالضبط.","14":"يتراجع الأسود بالحصان ليهرب. لكن هذا الحصان كان القطعة المهمة التي تحمي الجندي الأوسط. وبهروبه انفتحت ثغرة في الوسط. كان لدى الأسود دفاعات أخرى، لكن هذا كان أسوأ اختيار.","15":"يأخذ المدفع الأحمر الجندي الأوسط — كِش! بعد ذهاب الحصان الأسود صار الوسط مفتوحًا تمامًا. ومن هنا ينطلق هجوم الأحمر بسرعة.","16":"يرفع الأسود مستشارًا ليسدّ ما أمام الجنرال. هذه هي الطريقة الجيدة الوحيدة لصدّ الكِش.","17":"تصل العربة الحمراء الثانية إلى العمود نفسه. عربتان مصطفّتان في عمود واحد قوة هائلة. الخطة هي اقتحام عمق معسكر الأسود.","18":"يتنحّى الجنرال الأسود جانبًا. وإلا لحدّقت فيه العربتان الحمراوان من العمود نفسه.","19":"تأخذ العربة الحمراء الأمامية المستشار الأسود — كِش! سيأخذها المستشار الآخر فورًا، لكن هذا جزء من الخطة. يضحّي الأحمر بعربة ليحطّم حرس الجنرال الأسود. يا لها من نقلة جريئة!","20":"يأخذ الأسود العربة بالمستشار. في عدد القطع صار الأسود متقدّمًا كثيرًا. لكن بيت الجنرال صار أكثر فراغًا.","21":"تنتقل آخر عربة حمراء إلى عمود الجنرال — كِش مرة أخرى. لم يبقَ للجنرال الأسود تقريبًا أي قطعة تحميه.","22":"يضع الأسود مدفعًا أمام الجنرال ليسدّ الكِش. وضع قطعة في الوسط هكذا يُسمّى الاعتراض.","23":"تأخذ العربة الحمراء ذلك المدفع — كِش مجددًا. تواصل العربة أخذ القطع السوداء وهي تحاصر الجنرال.","24":"لا يستطيع الجنرال الأسود إلا العودة إلى الوسط. كل النقاط الأخرى تحت سيطرة القطع الحمراء.","25":"أخيرًا يقف المدفع الأحمر في الوسط: مدفعان في عمود واحد — كِش. المدفع الأمامي هو الحاجز والخلفي يضرب الجنرال: إنه مات «المدفع المزدوج». لا مكان يذهب إليه الجنرال الأسود، ويفوز الأحمر. بالتخلّي عن حصان واحد فقط فاز الأحمر في ثلاث عشرة نقلة. منذ 400 عام وهذه المباراة تعلّمنا أن الوقت ونشاط القطع قد يكونان أهم من عددها."}},"sokei1607":{"t":"أقدم مباراة شوغي محفوظة","w":"أوهاشي سوكي (الأول)","b":"هون-إنبو سانسا","ev":"أقدم مباراة مسجّلة","d":"يونيو 1607","pl":"اليابان (مكان اللعب غير مسجّل)","lead":"من بين كل مباريات الشوغي التي كُتبت نقلةً نقلة، هذه أقدم مباراة ما زالت بين أيدينا. السِّنتي هو سوكي، الذي أسّس لاحقًا بيت أوهاشي لأساتذة الشوغي. والغوتي هو سانسا، مؤسس بيت هون-إنبو للعبة غو، وكان قويًّا في الشوغي أيضًا. يفوز سوكي في 133 نقلة.","c":{"0":"أهلًا بكم، أنا Musowl. لُعبت هذه المباراة عام 1607، حين كان عصر إيدو قد بدأ للتوّ. السِّنتي أوهاشي سوكي سيُسمّى لاحقًا أول «ميجين»، أي أكبر أساتذة الشوغي في البلاد. والغوتي هون-إنبو سانسا أسّس بيت هون-إنبو للعبة غو وكان يجيد الشوغي كثيرًا؛ وكان الاثنان يلعبان كثيرًا أمام كبار القوم. بقيت ثماني مباريات بينهما بلا أفضلية، ويُقال إن سوكي فاز بسبع منها. وبعد أكثر من 400 سنة ما زلنا نستطيع إعادة كل نقلة.","1":"P-7f. تفتح هذه النقلة قطر الفيل، وما زالت حتى اليوم أكثر نقلة أولى شيوعًا. إذن كان الشوغي يبدأ هكذا قبل 400 سنة.","2":"P-3d. الغوتي أيضًا يفتح قطر فيله. الآن ينظر الفيلان أحدهما إلى الآخر عبر وسط الرقعة.","3":"S-4h. يرفع السِّنتي الفضة اليمنى. إنه يستعدّ لدفعها إلى الأمام.","5":"P-4f. يدفع السِّنتي بيدق العمود 4 ليُفسح مكانًا للفضة. وهي مرتبطة بالنقلة التالية S-4g.","6":"S-4b. الغوتي أيضًا يرفع فضة. المدافعون يتجمعون في العمود 4 لدى الغوتي.","10":"R-4b. ينقل الغوتي الرخ إلى العمود 4. يُسمّى هذا اليوم «رخ العمود الرابع»، وهو من خطط الرخ المنقول حيث يتحرك الرخ إلى اليسار. وكان يُلعب قبل 400 سنة.","11":"R-4h. رخ السِّنتي أيضًا يذهب إلى العمود 4، فيتقابل الرخّان. وسيحرّك السِّنتي هذا الرخ مرات كثيرة بحثًا عن مكان جيد للهجوم.","12":"B-3c. يتقدم الفيل خطوة ليقوّي العمود 4. جعل الغوتي هذا العمود متينًا جدًا.","16":"K-6b. ينقل الغوتي ملكه إلى اليسار. مع الرخ المنقول يختبئ الملك عادةً في الجهة المعاكسة للرخ. وكلما ابتعد عن القتال كان أكثر أمانًا.","17":"K-6h. السِّنتي أيضًا ينقل ملكه إلى اليسار. سيذهب بعدها إلى 7h ثم إلى 8g.","19":"K-7h. وصل الملك إلى العمود 7. الهدف التالي جمع الذهب والفضة حوله لبناء قلعة.","21":"G-5h. يقترب الذهب الأيمن من الملك. الذهب مدافع ممتاز، ووجوده قرب الملك يجعله في أمان.","24":"S-5c. يأتي الغوتي بفضة إلى العمود 5. ومع الفضتين في 5c و4c صار الوسط متينًا أيضًا.","29":"S-6g. تصل فضة السِّنتي قرب الملك. ومع الفضة في 6g والذهب في 7h يتكوّن جدار حول الملك.","30":"G-6c. يرفع الغوتي ذهبًا ليقوّي ما أمام ملكه. كلا اللاعبين يبني معسكره ببطء وعناية.","33":"P-8f. يدفع السِّنتي بيدق العمود 8 ليُفسح مكانًا للملك. إنه يستعدّ لـ K-8g.","35":"K-8g. يذهب الملك إلى 8g. ليست هذه قلعة مما نستعمله اليوم: الملك يقف عاليًا قرب الحافة. ونرى كيف كان لاعبو ذلك الزمان يفكرون في الدفاع.","36":"K-8b. يستقرّ ملك الغوتي في 8b. الآن كل ملك مختبئ جيدًا في زاويته.","39":"N-7g. يقفز الحصان إلى الأعلى ليستطيع القفز إلى 6e في أي وقت. يريد السِّنتي أن تساعد قطع القلعة في الهجوم أيضًا.","41":"R-3h. ينقل السِّنتي الرخ إلى العمود 3. العمود 4 لدى الغوتي قوي جدًا، فيغيّر السِّنتي مكان الهجوم.","42":"R-3b. ينقل الغوتي رخه فورًا إلى العمود 3 أيضًا. أينما ذهب رخ السِّنتي تبعه رخ الغوتي.","43":"P-2e. الآن يدفع السِّنتي بيدق العمود 2. الخطة أن ينقل الرخ إلى العمود 2 ويهاجم هناك.","44":"B-5a. يسحب الغوتي فيله إلى الخلف. يعيد ترتيب قطعه حتى تستطيع قطع أخرى صدّ هجوم على العمود 2.","45":"R-2h. عاد الرخ إلى عموده الأول، العمود 2. العمود 4 ثم 3 ثم 2: قام رخ السِّنتي برحلة طويلة.","46":"R-2b. يتبعه رخ الغوتي مرة أخرى إلى العمود 2. أينما أرسل السِّنتي رخه، استقبله الغوتي في العمود نفسه. «مطاردة الرخّين» هذه هي أجمل ما في الافتتاح.","47":"P-6e. الآن يبدأ السِّنتي القتال في العمود 6 حيث لا يوجد رخ. فبدل الهجوم حيث يراقب الرخّان أحدهما الآخر، يضرب حيث الغوتي أضعف. يبدأ وسط المباراة.","49":"Px6d. يدفع السِّنتي البيدق ويأسر. الفكرة جذب ذهب الغوتي إلى الأمام وإرخاء الدفاع حول الملك.","50":"Gx6d. يستردّ الغوتي بالذهب. ابتعد الذهب قليلًا عن ملكه، فتنفتح ثغرة صغيرة في الدفاع.","51":"P-4e. ثم يدفع السِّنتي بيدق العمود 4. إنه يهزّ دفاع الغوتي في هذا العمود أيضًا.","53":"N-3g. يقفز الحصان الآخر لينضمّ إلى الهجوم. قطع السِّنتي المهاجمة تتقدم واحدة بعد أخرى.","54":"P*6e. يُسقط الغوتي بيدقًا في 6e، المربع الذي يريد حصان السِّنتي القفز إليه. البيدق رخيص، لكنه مفيد جدًا لسدّ طريق قطعة الخصم.","56":"P-7e. يردّ الغوتي بهجوم مضاد. يضغط على العمود الذي فوق ملك السِّنتي مباشرة. إذا تحطمت البيادق فوق الملك صعب الدفاع عنه.","57":"Px7e. يأسر السِّنتي بالبيدق. وإلا لتقدم بيدق الغوتي حتى 7f.","58":"Gx7e. يستردّ الغوتي بالذهب الذي صار في 7e. يقدّم الغوتي ذهبه ليضغط على ملك السِّنتي.","59":"P*7f. يُسقط السِّنتي بيدقًا ليوقف الذهب. هذا البيدق يحمي رأس الملك.","61":"R-6i. يذهب رخ السِّنتي حتى أسفل العمود 6. يريد أن يضيف قوته إلى القتال في هذا العمود. لاحقًا ستأسره فضة الغوتي.","63":"Nx6e. يقفز الحصان من 7g ويأسر البيدق في 6e. الحصان الذي أعدّه السِّنتي منذ زمن يبدأ العمل أخيرًا.","64":"Nx6e. يستردّ الغوتي بحصانه. تبادل الطرفان الحصانين.","66":"P-8e. يضغط الغوتي من العمود 8 أيضًا. يحاول نزع البيادق أمام ملك السِّنتي واحدًا بعد آخر.","68":"P*7g. يُسقط الغوتي بيدقًا في 7g بجوار الملك مباشرة. إن أسره السِّنتي تُسحب القطعة الآسرة من مكانها، وإن لم يأسره يترقّى البيدق. إنها حيلة معروفة لكسر الدفاع ببيدق صغير.","69":"G-7i. يسحب السِّنتي الذهب إلى الخلف ليبتعد. يفضّل أن يحافظ على شكل دفاعه بدل أسر البيدق الآن.","70":"N*7e، كِش. يُسقط الغوتي حصانًا. يصل الحصان إلى الملك في 8g قافزًا فوق القطع الأخرى. يشتدّ هجوم الغوتي.","72":"Sx7e. بعد أن أسر بيدق السِّنتي الحصان، يستردّ الغوتي بالفضة ويتقدم. قطع الغوتي المهاجمة الآن بجوار ملك السِّنتي مباشرة.","74":"P*8f، كِش. يُسقط الغوتي بيدقًا آخر أمام الملك في 8g مباشرة. لم يعد الملك يستطيع البقاء هناك.","75":"K-9h. يهرب ملك السِّنتي إلى 9h على الحافة. يبتعد عن الخطر ويعيد بناء دفاعه.","77":"Px7e. الآن يأسر بيدق السِّنتي في 7f الفضة في 7e. يزيل السِّنتي قلب هجوم الغوتي ويحصل على فرصة للرد.","79":"S*7f. يُسقط السِّنتي فضة تصطدم بالذهب في 7e. تحمي رأس الملك وتحاول طرد الذهب.","81":"Sx7f. تبادل الطرفان الفضة والذهب. يقلّل السِّنتي مهاجمي الغوتي واحدًا بعد آخر.","83":"Px6e. يأسر بيدق 6f الحصان في 6e. يخسر الغوتي مهاجمًا آخر، وتزداد القطع في يد السِّنتي.","84":"S*7h. يُسقط الغوتي فضة تستهدف الرخ في 6i. سيخسر السِّنتي رخه، لكنه في الأثناء يسرّع هجومه.","85":"P*9b. من هنا يبدأ هجوم السِّنتي المضاد. بيدق يُسقط في 9b قرب ملك الغوتي يجذب الرمح إلى الأمام. تحريك القطع حول الملك يصنع ثغرات.","86":"Lx9b. يأسر الغوتي البيدق بالرمح. لكن الرمح صار في 9b وأصبح هدفًا للحصان التالي.","87":"N*8d. يُسقط السِّنتي حصانًا يهاجم معًا الرمح في 9b والذهب في 7b. مهاجمة هدفين في وقت واحد هي أبرع ما يفعله الحصان.","88":"B-5a. يسحب الغوتي فيله ليصوّب على الحصان في 8d عبر القطر. يريد أسره وإيقاف الهجوم.","89":"N*7d، كِش. يُسقط السِّنتي حصانه الآخر ويضع ملك الغوتي في كِش. الحصان يعطي كِشًا بالقفز فوق القطع، لذلك يصعب صدّه.","90":"K-8c. يصعد ملك الغوتي. وبتقدمه يقترب أيضًا من حصاني السِّنتي.","91":"Nx9b+. يأسر حصان 8d الرمح ويترقّى، فصار يتحرك مثل الذهب. دخل السِّنتي منطقة ملك الغوتي.","92":"Kx9b. يأسر الغوتي الحصان المترقّي بالملك. صار ملك الغوتي على الحافة في 9b.","93":"Bx7g. يأسر فيل السِّنتي البيدق في 7g. لم يتحرك هذا الفيل طوال المباراة، لكنه الآن يبدأ العمل. وسيكون له دور كبير لاحقًا.","94":"Sx6i+. تأسر فضة الغوتي رخ السِّنتي وتترقّى. خسارة الرخ كبيرة، لكن السِّنتي يرى أن هجومه على الملك أسرع.","95":"Gx6i. يستردّ السِّنتي الفضة المترقّية بالذهب. ذهب السِّنتي المدافع ما زال ثابتًا.","97":"P*9c، كِش. البيدق رخيص، لكنه إذا أُسقط أمام الملك مباشرة صار قويًا جدًا.","98":"K-8a. يتراجع ملك الغوتي إلى 8a. طرق هروبه تقلّ شيئًا فشيئًا.","99":"Bx8f. يأسر الفيل البيدق في 8f. وعبر قطره يرى الآن عمق معسكر الغوتي. إنه يستعدّ للنقلة الكبيرة التالية.","101":"G*9b، كِش. يعمل الذهب في 9b والبيدق في 9c معًا لطرد ملك الغوتي من الحافة.","103":"B-5c+. يطير فيل 8f حتى 5c ويترقّى إلى «حصان التنين». يتحرك مثل الفيل ومعها خطوة واحدة في أي اتجاه: قطعة قوية جدًا. دخلت قطعة السِّنتي الكبيرة قرب ملك الغوتي.","104":"K-6a. يواصل ملك الغوتي الهروب نحو العمود 6. إنه يُدفع من الحافة نحو وسط الرقعة.","105":"L*6d. يُسقط السِّنتي رمحًا. يتحرك الرمح إلى الأمام مستقيمًا مهما شاء، فيراقب العمود 6 كله.","106":"P*6b. يُسقط الغوتي بيدقًا ليسدّ طريق الرمح.","107":"+Bx4c. يأسر حصان التنين الفضة في 4c. يخسر الغوتي مدافعًا آخر.","108":"N*5b. يُسقط الغوتي حصانًا ليقوّي دفاعه. الوضع صعب، لكن الغوتي يواصل القتال.","109":"K-8g. هنا يرفع السِّنتي ملكه مرة إلى 8g. يبدو أنه يعطي الملك مساحة أكبر قبل أن يردّ الغوتي.","110":"R*8i، كِش. يردّ الغوتي بإسقاط رخ مع كِش. الغوتي أيضًا يحاول الإمساك بملك السِّنتي.","112":"P-7g+، كِش. يترقّى البيدق إلى «توكين» ويعطي كِشًا. التوكين يتحرك مثل الذهب، لكن إن أُسر لا يحصل الخصم إلا على بيدق.","114":"Rx6i+. يأسر الرخ الذهب ويصير تنينًا. فقد ملك السِّنتي مدافعيه، وصارت المباراة سباقًا: من يمسك ملك الآخر أولًا؟","115":"S*5c. يُسقط السِّنتي فضة ليضيّق الشبكة حول ملك الغوتي. الضغط على ملك الخصم حتى وملكك في خطر هو جوهر مثل هذا السباق.","116":"S*6f، كِش. يُسقط الغوتي فضة ويعطي كِشًا. على ملك السِّنتي أن يهرب.","117":"K-8f. يهرب الملك إلى 8f. لملك السِّنتي مساحة واسعة إلى الأعلى.","119":"K-9e. يواصل الملك حتى 9e على الحافة. هنا تكاد قطع الغوتي لا تصل إليه. صار ملك السِّنتي آمنًا مؤقتًا، فيستطيع التركيز على الهجوم.","120":"P-6c. يدفع الغوتي بيدقًا للدفاع. لكن دفاع الغوتي لم يعد كافيًا.","121":"S*6b. هنا يبدأ السِّنتي الإنهاء. يُسقط فضة داخل معسكر الغوتي ليأسر القطع التي تحرس الملك.","122":"Bx6b. يأسر الغوتي الفضة بالفيل.","123":"Sx6b+. تأسر فضة 5c الفيل وتترقّى. يخسر الغوتي قطعة كبيرة.","125":"Nx6b+. ويأسر حصان 7d الذهب ويترقّى أيضًا. قطعةً بقطعة، يُعرّي السِّنتي دفاع الغوتي.","126":"Kx6b. يأسر الغوتي بالملك. لكن لم يبقَ تقريبًا أي مدافع حول ملك الغوتي.","127":"B*5c، كِش. يُسقط السِّنتي الفيل الذي أسره للتو. استعمال القطع المأسورة فورًا هو ما يجعل الشوغي مثيرًا جدًا.","129":"G*8d، كِش. يغلق الذهب طريق هروب الملك من الأعلى.","131":"P*7c، كِش. لا خيار لملك الغوتي إلا أن يعود إلى الخلف.","133":"Lx6c+. يأسر الرمح البيدق في 6c ويترقّى. رأى سانسا أنه إذا دخلت قطعة إلى 6b في النقلة التالية فلن يبقى للملك مهرب، فاستسلم هنا. يفوز سوكي في 133 نقلة. أبرز ما فيها: «مطاردة الرخّين» في الافتتاح، وشدّ الحبل بالبيادق والأحصنة في الوسط، والنهاية التي ضحّى فيها السِّنتي برخه ليسابق نحو الملك. تُظهر هذه المباراة كيف ترتبط أفكار أستاذ عاش قبل 400 سنة بشوغي اليوم."}}};
